INSERT INTO public.form_template_versions VALUES ('8bc6cd74-1a00-454d-b164-5d0a31f26516', '82b81c36-08b8-4c23-8ae5-b26f51efdf48', 1, '{"sections": [{"id": "project_info", "order": 1, "title": "Project Information", "fields": [{"id": "date", "type": "date", "label": "Date", "required": true, "validation": {"max": "{{currentDate}}"}, "defaultValue": "{{currentDate}}"}, {"id": "project_name", "type": "text", "label": "Project Name", "readonly": true, "required": true, "defaultValue": "{{projectName}}"}, {"id": "location", "type": "text", "label": "Location/Address", "readonly": true, "required": true, "defaultValue": "{{projectLocation}}"}, {"id": "prepared_by", "type": "text", "label": "Prepared By", "readonly": true, "required": true, "defaultValue": "{{currentUser}}"}]}, {"id": "weather", "order": 2, "title": "Weather Conditions", "fields": [{"id": "temperature_high", "type": "number", "label": "High Temperature (°F)", "required": true, "validation": {"max": 150, "min": -50}}, {"id": "temperature_low", "type": "number", "label": "Low Temperature (°F)", "required": false, "validation": {"max": 150, "min": -50}}, {"id": "conditions", "type": "select", "label": "Weather Conditions", "options": [{"label": "Clear", "value": "clear"}, {"label": "Partly Cloudy", "value": "partly_cloudy"}, {"label": "Cloudy", "value": "cloudy"}, {"label": "Rain", "value": "rain"}, {"label": "Heavy Rain", "value": "heavy_rain"}, {"label": "Snow", "value": "snow"}, {"label": "Fog", "value": "fog"}, {"label": "Windy", "value": "wind"}], "required": true}, {"id": "precipitation", "type": "number", "label": "Precipitation (inches)", "required": false, "validation": {"max": 20, "min": 0, "precision": 2}, "conditionalDisplay": {"field": "conditions", "value": ["rain", "heavy_rain", "snow"], "operator": "in"}}, {"id": "wind_speed", "type": "number", "label": "Wind Speed (mph)", "required": false, "validation": {"max": 100, "min": 0}}]}, {"id": "work_performed", "order": 3, "title": "Work Performed", "fields": [{"id": "work_description", "type": "textarea", "label": "Description of Work Activities", "required": true, "validation": {"maxLength": 2000, "minLength": 10}, "placeholder": "Describe the work performed today..."}, {"id": "work_areas", "type": "textarea", "label": "Work Areas/Locations", "required": false, "validation": {"maxLength": 500}, "placeholder": "List areas where work was performed..."}, {"id": "percent_complete", "type": "number", "label": "Overall Project % Complete", "required": false, "validation": {"max": 100, "min": 0}}]}, {"id": "labor", "order": 4, "title": "Labor Hours", "fields": [{"id": "labor_breakdown", "type": "repeater", "label": "Labor by Trade", "maxItems": 20, "minItems": 0, "required": false, "itemSchema": {"fields": [{"id": "trade", "type": "select", "label": "Trade", "options": [{"label": "Carpenter", "value": "carpenter"}, {"label": "Laborer", "value": "laborer"}, {"label": "Equipment Operator", "value": "operator"}, {"label": "Electrician", "value": "electrician"}, {"label": "Plumber", "value": "plumber"}, {"label": "Mason", "value": "mason"}, {"label": "Ironworker", "value": "ironworker"}, {"label": "Concrete Finisher", "value": "concrete_finisher"}, {"label": "Foreman", "value": "foreman"}, {"label": "Superintendent", "value": "superintendent"}, {"label": "Other", "value": "other"}], "required": true}, {"id": "trade_other", "type": "text", "label": "Specify Other Trade", "required": true, "conditionalDisplay": {"field": "trade", "value": "other", "operator": "equals"}}, {"id": "worker_count", "type": "number", "label": "Number of Workers", "required": true, "validation": {"max": 100, "min": 1}}, {"id": "hours", "type": "number", "label": "Hours Worked", "required": true, "validation": {"max": 24, "min": 0, "precision": 1}}]}}, {"id": "total_labor_hours", "type": "number", "label": "Total Labor Hours", "computed": {"formula": "SUM(labor_breakdown.*.worker_count * labor_breakdown.*.hours)"}, "readonly": true, "required": false}]}, {"id": "equipment", "order": 5, "title": "Equipment Used", "fields": [{"id": "equipment_list", "type": "repeater", "label": "Equipment on Site", "maxItems": 30, "minItems": 0, "required": false, "itemSchema": {"fields": [{"id": "equipment_type", "type": "select", "label": "Equipment Type", "options": [{"label": "Excavator", "value": "excavator"}, {"label": "Loader", "value": "loader"}, {"label": "Dozer", "value": "dozer"}, {"label": "Backhoe", "value": "backhoe"}, {"label": "Crane", "value": "crane"}, {"label": "Forklift", "value": "forklift"}, {"label": "Concrete Pump", "value": "concrete_pump"}, {"label": "Concrete Mixer Truck", "value": "mixer_truck"}, {"label": "Dump Truck", "value": "dump_truck"}, {"label": "Scissor Lift", "value": "scissor_lift"}, {"label": "Boom Lift", "value": "boom_lift"}, {"label": "Compactor", "value": "compactor"}, {"label": "Generator", "value": "generator"}, {"label": "Other", "value": "other"}], "required": true}, {"id": "equipment_id", "type": "text", "label": "Equipment ID/Number", "required": false}, {"id": "hours_operated", "type": "number", "label": "Hours Operated", "required": false, "validation": {"max": 24, "min": 0, "precision": 1}}]}}]}, {"id": "materials", "order": 6, "title": "Materials Delivered/Received", "fields": [{"id": "materials_list", "type": "repeater", "label": "Materials", "maxItems": 30, "minItems": 0, "required": false, "itemSchema": {"fields": [{"id": "material_description", "type": "text", "label": "Material Description", "required": true, "validation": {"maxLength": 200}}, {"id": "quantity", "type": "text", "label": "Quantity (with unit)", "required": true, "validation": {"maxLength": 100}, "placeholder": "e.g., 50 cubic yards, 100 pieces"}, {"id": "supplier", "type": "text", "label": "Supplier", "required": false, "validation": {"maxLength": 100}}]}}]}, {"id": "subcontractors", "order": 7, "title": "Subcontractors & Visitors", "fields": [{"id": "subcontractors_list", "type": "repeater", "label": "Subcontractors on Site", "maxItems": 20, "minItems": 0, "required": false, "itemSchema": {"fields": [{"id": "company_name", "type": "text", "label": "Company Name", "required": true, "validation": {"maxLength": 150}}, {"id": "trade_work", "type": "text", "label": "Trade/Work Performed", "required": true, "validation": {"maxLength": 150}}, {"id": "worker_count", "type": "number", "label": "Number of Workers", "required": false, "validation": {"max": 100, "min": 1}}]}}, {"id": "visitors_list", "type": "repeater", "label": "Visitors", "maxItems": 20, "minItems": 0, "required": false, "itemSchema": {"fields": [{"id": "visitor_name", "type": "text", "label": "Visitor Name", "required": true, "validation": {"maxLength": 100}}, {"id": "company", "type": "text", "label": "Company", "required": false, "validation": {"maxLength": 100}}, {"id": "purpose", "type": "text", "label": "Purpose of Visit", "required": false, "validation": {"maxLength": 200}}]}}]}, {"id": "delays_issues", "order": 8, "title": "Delays & Issues", "fields": [{"id": "delays_occurred", "type": "radio", "label": "Were there any delays today?", "options": [{"label": "Yes", "value": "yes"}, {"label": "No", "value": "no"}], "required": true, "defaultValue": "no"}, {"id": "delay_description", "type": "textarea", "label": "Delay Description", "required": true, "validation": {"maxLength": 1000, "minLength": 10}, "placeholder": "Describe the delay and its cause...", "conditionalDisplay": {"field": "delays_occurred", "value": "yes", "operator": "equals"}}, {"id": "issues_problems", "type": "textarea", "label": "Problems/Issues Encountered", "required": false, "validation": {"maxLength": 1000}, "placeholder": "Describe any problems or issues..."}]}, {"id": "safety", "order": 9, "title": "Safety Incidents", "fields": [{"id": "safety_incidents", "type": "radio", "label": "Were there any safety incidents today?", "options": [{"label": "Yes", "value": "yes"}, {"label": "No", "value": "no"}], "required": true, "defaultValue": "no"}, {"id": "incident_description", "type": "textarea", "label": "Incident Description", "helpText": "Note: Complete a separate Incident Report for all injuries", "required": true, "validation": {"maxLength": 1000, "minLength": 10}, "placeholder": "Describe the safety incident...", "conditionalDisplay": {"field": "safety_incidents", "value": "yes", "operator": "equals"}}]}, {"id": "photos", "order": 10, "title": "Photos", "fields": [{"id": "daily_photos", "type": "photo", "label": "Daily Progress Photos", "helpText": "Capture photos of work progress, conditions, and activities", "multiple": true, "required": false, "maxPhotos": 20, "captureGPS": true}]}, {"id": "signature", "order": 11, "title": "Approval", "fields": [{"id": "notes", "type": "textarea", "label": "Additional Notes", "required": false, "validation": {"maxLength": 1000}, "placeholder": "Any additional information..."}, {"id": "prepared_by_signature", "type": "signature", "label": "Foreman/Superintendent Signature", "required": true, "captureTimestamp": true}]}]}', 'Initial system template from 01-general-daily-log.json', '2025-10-24 13:30:31.331', 'system');
INSERT INTO public.form_template_versions VALUES ('8dd4ad74-81ef-432d-8dee-4b810a3d5169', '3a3c9ab8-a4f7-4d3a-a7ca-742f29646a90', 1, '{"sections": [{"id": "project_info", "order": 1, "title": "Project Information", "fields": [{"id": "date", "type": "date", "label": "Date", "required": true, "validation": {"max": "{{currentDate}}"}, "defaultValue": "{{currentDate}}"}, {"id": "project_name", "type": "text", "label": "Project Name", "readonly": true, "required": true, "defaultValue": "{{projectName}}"}, {"id": "superintendent", "type": "text", "label": "Superintendent", "readonly": true, "required": true, "defaultValue": "{{currentUser}}"}, {"id": "shift", "type": "select", "label": "Shift", "options": [{"label": "Day Shift", "value": "day"}, {"label": "Night Shift", "value": "night"}, {"label": "Both Shifts", "value": "both"}], "required": true, "defaultValue": "day"}]}, {"id": "weather", "order": 2, "title": "Weather Conditions", "fields": [{"id": "temperature", "type": "number", "label": "Temperature (°F)", "required": true, "validation": {"max": 150, "min": -50}}, {"id": "conditions", "type": "select", "label": "Weather Conditions", "options": [{"label": "Clear", "value": "clear"}, {"label": "Cloudy", "value": "cloudy"}, {"label": "Rain", "value": "rain"}, {"label": "Snow", "value": "snow"}, {"label": "Fog", "value": "fog"}, {"label": "Windy", "value": "wind"}], "required": true}, {"id": "weather_impact", "type": "radio", "label": "Did weather impact work?", "options": [{"label": "No Impact", "value": "no_impact"}, {"label": "Minor Impact", "value": "minor_impact"}, {"label": "Significant Impact", "value": "significant_impact"}, {"label": "Work Stopped", "value": "work_stopped"}], "required": true, "defaultValue": "no_impact"}, {"id": "weather_impact_notes", "type": "textarea", "label": "Weather Impact Notes", "required": true, "validation": {"maxLength": 500, "minLength": 10}, "conditionalDisplay": {"field": "weather_impact", "value": ["minor_impact", "significant_impact", "work_stopped"], "operator": "in"}}]}, {"id": "schedule", "order": 3, "title": "Schedule Status", "fields": [{"id": "schedule_status", "type": "select", "label": "Schedule Status", "options": [{"label": "Ahead of Schedule", "value": "ahead"}, {"label": "On Track", "value": "on_track"}, {"label": "Behind Schedule", "value": "behind"}, {"label": "Critical Delay", "value": "critical"}], "required": true}, {"id": "days_ahead_behind", "type": "number", "label": "Days Ahead/Behind (- for behind)", "helpText": "Enter negative number if behind schedule", "required": false, "validation": {"max": 365, "min": -365}}, {"id": "critical_path_activities", "type": "textarea", "label": "Critical Path Activities in Progress", "required": false, "validation": {"maxLength": 1000}, "placeholder": "List critical path activities..."}]}, {"id": "work_progress", "order": 4, "title": "Work Progress", "fields": [{"id": "work_summary", "type": "textarea", "label": "Work Progress Summary", "required": true, "validation": {"maxLength": 2000, "minLength": 20}, "placeholder": "Summarize work completed today..."}, {"id": "major_activities", "type": "repeater", "label": "Major Activities Completed", "maxItems": 15, "minItems": 0, "required": false, "itemSchema": {"fields": [{"id": "activity", "type": "text", "label": "Activity Description", "required": true, "validation": {"maxLength": 200}}, {"id": "location", "type": "text", "label": "Location", "required": false, "validation": {"maxLength": 100}}, {"id": "percent_complete", "type": "number", "label": "% Complete", "required": false, "validation": {"max": 100, "min": 0}}]}}]}, {"id": "labor", "order": 5, "title": "Labor Breakdown", "fields": [{"id": "total_workers", "type": "number", "label": "Total Workers on Site", "required": true, "validation": {"max": 500, "min": 0}}, {"id": "labor_by_trade", "type": "repeater", "label": "Labor by Trade/Company", "maxItems": 20, "minItems": 0, "required": false, "itemSchema": {"fields": [{"id": "trade_or_company", "type": "text", "label": "Trade or Company", "required": true, "validation": {"maxLength": 100}}, {"id": "worker_count", "type": "number", "label": "Number of Workers", "required": true, "validation": {"max": 200, "min": 1}}, {"id": "work_description", "type": "text", "label": "Work Performed", "required": false, "validation": {"maxLength": 150}}]}}]}, {"id": "equipment", "order": 6, "title": "Equipment & Materials", "fields": [{"id": "major_equipment", "type": "textarea", "label": "Major Equipment on Site", "required": false, "validation": {"maxLength": 1000}, "placeholder": "List major equipment in use..."}, {"id": "materials_received", "type": "repeater", "label": "Materials Received", "maxItems": 20, "minItems": 0, "required": false, "itemSchema": {"fields": [{"id": "material", "type": "text", "label": "Material", "required": true, "validation": {"maxLength": 150}}, {"id": "quantity", "type": "text", "label": "Quantity", "required": true, "validation": {"maxLength": 100}}, {"id": "supplier", "type": "text", "label": "Supplier", "required": false, "validation": {"maxLength": 100}}]}}]}, {"id": "inspections", "order": 7, "title": "Inspections & Testing", "fields": [{"id": "inspections_conducted", "type": "radio", "label": "Were inspections conducted today?", "options": [{"label": "Yes", "value": "yes"}, {"label": "No", "value": "no"}], "required": true, "defaultValue": "no"}, {"id": "inspection_list", "type": "repeater", "label": "Inspections", "maxItems": 15, "minItems": 1, "required": true, "itemSchema": {"fields": [{"id": "inspection_type", "type": "text", "label": "Inspection Type", "required": true, "validation": {"maxLength": 150}, "placeholder": "e.g., Concrete slump test, Building inspection"}, {"id": "inspector", "type": "text", "label": "Inspector/Agency", "required": true, "validation": {"maxLength": 100}}, {"id": "result", "type": "select", "label": "Result", "options": [{"label": "Passed", "value": "passed"}, {"label": "Failed", "value": "failed"}, {"label": "Conditional Approval", "value": "conditional"}, {"label": "Pending", "value": "pending"}], "required": true}, {"id": "notes", "type": "textarea", "label": "Notes", "required": false, "validation": {"maxLength": 500}}]}, "conditionalDisplay": {"field": "inspections_conducted", "value": "yes", "operator": "equals"}}]}, {"id": "issues_delays", "order": 8, "title": "Issues & Delays", "fields": [{"id": "issues_today", "type": "textarea", "label": "Issues/Problems Encountered", "required": false, "validation": {"maxLength": 1500}, "placeholder": "Describe issues encountered today..."}, {"id": "delays_description", "type": "textarea", "label": "Delays & Causes", "required": false, "validation": {"maxLength": 1500}, "placeholder": "Describe any delays and their causes..."}]}, {"id": "change_orders_rfis", "order": 9, "title": "Change Orders & RFIs", "fields": [{"id": "change_orders", "type": "repeater", "label": "Change Orders in Progress", "maxItems": 15, "minItems": 0, "required": false, "itemSchema": {"fields": [{"id": "co_number", "type": "text", "label": "CO Number", "required": true, "validation": {"maxLength": 50}}, {"id": "description", "type": "text", "label": "Description", "required": true, "validation": {"maxLength": 200}}, {"id": "status", "type": "select", "label": "Status", "options": [{"label": "Pending Approval", "value": "pending_approval"}, {"label": "Approved", "value": "approved"}, {"label": "In Progress", "value": "in_progress"}, {"label": "Completed", "value": "completed"}], "required": true}]}}, {"id": "rfis", "type": "repeater", "label": "RFIs Submitted/Pending", "maxItems": 15, "minItems": 0, "required": false, "itemSchema": {"fields": [{"id": "rfi_number", "type": "text", "label": "RFI Number", "required": true, "validation": {"maxLength": 50}}, {"id": "subject", "type": "text", "label": "Subject", "required": true, "validation": {"maxLength": 200}}, {"id": "status", "type": "select", "label": "Status", "options": [{"label": "Submitted", "value": "submitted"}, {"label": "Under Review", "value": "under_review"}, {"label": "Answered", "value": "answered"}, {"label": "Closed", "value": "closed"}], "required": true}]}}]}, {"id": "safety", "order": 10, "title": "Safety Observations", "fields": [{"id": "safety_meetings", "type": "radio", "label": "Safety meetings/toolbox talks held?", "options": [{"label": "Yes", "value": "yes"}, {"label": "No", "value": "no"}], "required": true, "defaultValue": "no"}, {"id": "safety_meeting_topics", "type": "text", "label": "Safety Meeting Topics", "required": true, "validation": {"maxLength": 200}, "conditionalDisplay": {"field": "safety_meetings", "value": "yes", "operator": "equals"}}, {"id": "safety_incidents", "type": "radio", "label": "Any safety incidents today?", "options": [{"label": "Yes", "value": "yes"}, {"label": "No", "value": "no"}], "required": true, "defaultValue": "no"}, {"id": "incident_summary", "type": "textarea", "label": "Incident Summary", "helpText": "Complete separate Incident Report for all injuries", "required": true, "validation": {"maxLength": 1000, "minLength": 10}, "conditionalDisplay": {"field": "safety_incidents", "value": "yes", "operator": "equals"}}, {"id": "safety_observations", "type": "textarea", "label": "Safety Observations/Concerns", "required": false, "validation": {"maxLength": 1000}, "placeholder": "Note any safety concerns or positive observations..."}]}, {"id": "photos", "order": 11, "title": "Documentation", "fields": [{"id": "progress_photos", "type": "photo", "label": "Progress Photos", "helpText": "Document progress, conditions, and key activities", "multiple": true, "required": false, "maxPhotos": 30, "captureGPS": true}]}, {"id": "signature", "order": 12, "title": "Approval", "fields": [{"id": "notes", "type": "textarea", "label": "Additional Notes/Remarks", "required": false, "validation": {"maxLength": 1500}, "placeholder": "Any additional information for the project record..."}, {"id": "superintendent_signature", "type": "signature", "label": "Superintendent Signature", "required": true, "captureTimestamp": true}]}]}', 'Initial system template from 02-superintendent-daily-report.json', '2025-10-24 13:30:31.343', 'system');
INSERT INTO public.form_template_versions VALUES ('342d7ac0-f67c-4dff-a7c3-0bf57d918768', '5bc9fbef-25c7-47ed-a3b3-233ced83ba81', 1, '{"sections": [{"id": "inspector_info", "order": 1, "title": "Inspector Information", "fields": [{"id": "date", "type": "date", "label": "Inspection Date", "required": true, "validation": {"max": "{{currentDate}}"}, "defaultValue": "{{currentDate}}"}, {"id": "inspector_name", "type": "text", "label": "Inspector Name", "readonly": true, "required": true, "defaultValue": "{{currentUser}}"}, {"id": "site_location", "type": "text", "label": "Site Location", "readonly": true, "required": true, "defaultValue": "{{projectLocation}}"}, {"id": "inspection_time", "type": "time", "label": "Inspection Time", "required": true, "defaultValue": "{{currentTime}}"}, {"id": "weather_conditions", "type": "select", "label": "Weather Conditions", "options": [{"label": "Clear", "value": "clear"}, {"label": "Cloudy", "value": "cloudy"}, {"label": "Rain", "value": "rain"}, {"label": "Snow", "value": "snow"}, {"label": "Windy", "value": "wind"}, {"label": "Extreme Heat", "value": "extreme_heat"}, {"label": "Extreme Cold", "value": "extreme_cold"}], "required": true}]}, {"id": "ppe", "order": 2, "title": "Personal Protective Equipment (PPE)", "fields": [{"id": "hard_hats", "type": "select", "label": "Hard Hats", "options": [{"label": "Compliant - All workers wearing", "value": "compliant"}, {"label": "Needs Correction", "value": "needs_correction"}, {"label": "Non-Compliant", "value": "non_compliant"}, {"label": "N/A", "value": "not_applicable"}], "required": true}, {"id": "safety_glasses", "type": "select", "label": "Safety Glasses/Eye Protection", "options": [{"label": "Compliant - All workers wearing", "value": "compliant"}, {"label": "Needs Correction", "value": "needs_correction"}, {"label": "Non-Compliant", "value": "non_compliant"}, {"label": "N/A", "value": "not_applicable"}], "required": true}, {"id": "gloves", "type": "select", "label": "Gloves (where required)", "options": [{"label": "Compliant", "value": "compliant"}, {"label": "Needs Correction", "value": "needs_correction"}, {"label": "Non-Compliant", "value": "non_compliant"}, {"label": "N/A", "value": "not_applicable"}], "required": true}, {"id": "safety_boots", "type": "select", "label": "Safety Boots/Footwear", "options": [{"label": "Compliant", "value": "compliant"}, {"label": "Needs Correction", "value": "needs_correction"}, {"label": "Non-Compliant", "value": "non_compliant"}, {"label": "N/A", "value": "not_applicable"}], "required": true}, {"id": "high_visibility_vests", "type": "select", "label": "High-Visibility Vests", "options": [{"label": "Compliant", "value": "compliant"}, {"label": "Needs Correction", "value": "needs_correction"}, {"label": "Non-Compliant", "value": "non_compliant"}, {"label": "N/A", "value": "not_applicable"}], "required": true}, {"id": "hearing_protection", "type": "select", "label": "Hearing Protection (where required)", "options": [{"label": "Compliant", "value": "compliant"}, {"label": "Needs Correction", "value": "needs_correction"}, {"label": "Non-Compliant", "value": "non_compliant"}, {"label": "N/A", "value": "not_applicable"}], "required": true}, {"id": "respiratory_protection", "type": "select", "label": "Respiratory Protection (where required)", "options": [{"label": "Compliant", "value": "compliant"}, {"label": "Needs Correction", "value": "needs_correction"}, {"label": "Non-Compliant", "value": "non_compliant"}, {"label": "N/A", "value": "not_applicable"}], "required": true}, {"id": "ppe_notes", "type": "textarea", "label": "PPE Issues/Notes", "required": false, "validation": {"maxLength": 1000}, "placeholder": "Describe any PPE issues or corrective actions..."}]}, {"id": "fall_protection", "order": 3, "title": "Fall Protection Systems", "fields": [{"id": "guardrails", "type": "select", "label": "Guardrails/Barriers", "options": [{"label": "Compliant - Properly installed", "value": "compliant"}, {"label": "Needs 