- Covered/secured", "value": "compliant"}, {"label": "Needs Correction", "value": "needs_correction"}, {"label": "Non-Compliant - Exposed/damaged", "value": "non_compliant"}, {"label": "N/A", "value": "not_applicable"}], "required": true}, {"id": "lockout_tagout", "type": "select", "label": "Lockout/Tagout (if applicable)", "options": [{"label": "Compliant - Procedures followed", "value": "compliant"}, {"label": "Needs Correction", "value": "needs_correction"}, {"label": "Non-Compliant", "value": "non_compliant"}, {"label": "N/A", "value": "not_applicable"}], "required": true}, {"id": "electrical_notes", "type": "textarea", "label": "Electrical Safety Issues/Notes", "required": false, "validation": {"maxLength": 1000}, "placeholder": "Describe any issues or corrective actions..."}]}, {"id": "fire_first_aid", "order": 6, "title": "Fire Safety & First Aid", "fields": [{"id": "fire_extinguishers", "type": "select", "label": "Fire Extinguishers", "options": [{"label": "Compliant - Available/inspected", "value": "compliant"}, {"label": "Needs Correction", "value": "needs_correction"}, {"label": "Non-Compliant - Missing/expired", "value": "non_compliant"}, {"label": "N/A", "value": "not_applicable"}], "required": true}, {"id": "fire_exits", "type": "select", "label": "Fire Exits/Emergency Routes", "options": [{"label": "Compliant - Clear and marked", "value": "compliant"}, {"label": "Needs Correction", "value": "needs_correction"}, {"label": "Non-Compliant - Blocked/unmarked", "value": "non_compliant"}, {"label": "N/A", "value": "not_applicable"}], "required": true}, {"id": "first_aid_kits", "type": "select", "label": "First Aid Kits", "options": [{"label": "Compliant - Available and stocked", "value": "compliant"}, {"label": "Needs Correction", "value": "needs_correction"}, {"label": "Non-Compliant - Missing/depleted", "value": "non_compliant"}, {"label": "N/A", "value": "not_applicable"}], "required": true}, {"id": "eyewash_stations", "type": "select", "label": "Eyewash Stations (if required)", "options": [{"label": "Compliant - Functional", "value": "compliant"}, {"label": "Needs Correction", "value": "needs_correction"}, {"label": "Non-Compliant", "value": "non_compliant"}, {"label": "N/A", "value": "not_applicable"}], "required": true}]}, {"id": "tools_equipment", "order": 7, "title": "Tools & Equipment", "fields": [{"id": "power_tools", "type": "select", "label": "Power Tools Condition", "options": [{"label": "Compliant - Good condition, guards in place", "value": "compliant"}, {"label": "Needs Correction", "value": "needs_correction"}, {"label": "Non-Compliant - Damaged/missing guards", "value": "non_compliant"}, {"label": "N/A", "value": "not_applicable"}], "required": true}, {"id": "heavy_equipment", "type": "select", "label": "Heavy Equipment Safety", "options": [{"label": "Compliant - Inspected, backup alarms working", "value": "compliant"}, {"label": "Needs Correction", "value": "needs_correction"}, {"label": "Non-Compliant", "value": "non_compliant"}, {"label": "N/A", "value": "not_applicable"}], "required": true}, {"id": "tool_storage", "type": "select", "label": "Tool Storage/Organization", "options": [{"label": "Compliant - Organized, no trip hazards", "value": "compliant"}, {"label": "Needs Correction", "value": "needs_correction"}, {"label": "Non-Compliant", "value": "non_compliant"}, {"label": "N/A", "value": "not_applicable"}], "required": true}]}, {"id": "hazard_communication", "order": 8, "title": "Hazard Communication & Training", "fields": [{"id": "safety_signage", "type": "select", "label": "Safety Signage/Warnings", "options": [{"label": "Compliant - Adequate signs posted", "value": "compliant"}, {"label": "Needs Correction", "value": "needs_correction"}, {"label": "Non-Compliant - Missing/inadequate", "value": "non_compliant"}, {"label": "N/A", "value": "not_applicable"}], "required": true}, {"id": "sds_availability", "type": "select", "label": "SDS (Safety Data Sheets) Available", "options": [{"label": "Compliant - SDS accessible", "value": "compliant"}, {"label": "Needs Correction", "value": "needs_correction"}, {"label": "Non-Compliant - Not available", "value": "non_compliant"}, {"label": "N/A", "value": "not_applicable"}], "required": true}, {"id": "training_verification", "type": "select", "label": "Worker Training Verification", "options": [{"label": "Compliant - Workers trained for tasks", "value": "compliant"}, {"label": "Needs Correction", "value": "needs_correction"}, {"label": "Non-Compliant - Untrained workers", "value": "non_compliant"}, {"label": "N/A", "value": "not_applicable"}], "required": true}]}, {"id": "corrective_actions", "order": 9, "title": "Corrective Actions Required", "fields": [{"id": "corrective_actions_needed", "type": "radio", "label": "Are corrective actions needed?", "options": [{"label": "Yes", "value": "yes"}, {"label": "No", "value": "no"}], "required": true, "defaultValue": "no"}, {"id": "actions_list", "type": "repeater", "label": "Corrective Actions", "maxItems": 20, "minItems": 1, "required": true, "itemSchema": {"fields": [{"id": "hazard_description", "type": "text", "label": "Hazard/Issue Description", "required": true, "validation": {"maxLength": 200}}, {"id": "severity", "type": "select", "label": "Severity", "options": [{"label": "Immediate Danger - Stop Work", "value": "immediate"}, {"label": "High Priority - Fix Today", "value": "high"}, {"label": "Medium Priority - Fix This Week", "value": "medium"}, {"label": "Low Priority", "value": "low"}], "required": true}, {"id": "corrective_action", "type": "text", "label": "Corrective Action Required", "required": true, "validation": {"maxLength": 200}}, {"id": "responsible_person", "type": "text", "label": "Responsible Person", "required": true, "validation": {"maxLength": 100}}, {"id": "due_date", "type": "date", "label": "Due Date", "required": true}]}, "conditionalDisplay": {"field": "corrective_actions_needed", "value": "yes", "operator": "equals"}}]}, {"id": "photos", "order": 10, "title": "Photo Documentation", "fields": [{"id": "inspection_photos", "type": "photo", "label": "Inspection Photos", "helpText": "Photograph hazards, conditions, and corrective actions", "multiple": true, "required": false, "maxPhotos": 30, "captureGPS": true}]}, {"id": "signature", "order": 11, "title": "Inspector Certification", "fields": [{"id": "overall_assessment", "type": "select", "label": "Overall Site Safety Assessment", "options": [{"label": "Excellent - No issues", "value": "excellent"}, {"label": "Good - Minor issues corrected", "value": "good"}, {"label": "Fair - Corrective actions required", "value": "fair"}, {"label": "Poor - Major safety concerns", "value": "poor"}, {"label": "Critical - Work stopped", "value": "critical"}], "required": true}, {"id": "notes", "type": "textarea", "label": "Additional Notes/Comments", "required": false, "validation": {"maxLength": 1500}, "placeholder": "Any additional safety observations or concerns..."}, {"id": "inspector_signature", "type": "signature", "label": "Inspector Signature", "helpText": "I certify this inspection was conducted per OSHA requirements", "required": true, "captureTimestamp": true}]}]}', 'Initial system template from 03-daily-safety-inspection.json', '2025-10-24 13:30:31.356', 'system');
INSERT INTO public.form_template_versions VALUES ('1e95c8a8-d6c6-40be-b79f-fcfc54981c62', 'f720e053-980c-4ff5-80bd-13ce4ab1c1ea', 1, '{"sections": [{"id": "meeting_info", "order": 1, "title": "Meeting Information", "fields": [{"id": "date", "type": "date", "label": "Meeting Date", "required": true, "validation": {"max": "{{currentDate}}"}, "defaultValue": "{{currentDate}}"}, {"id": "time", "type": "time", "label": "Meeting Time", "required": true, "defaultValue": "{{currentTime}}"}, {"id": "location", "type": "text", "label": "Location", "required": true, "placeholder": "e.g., Job site trailer, Main gate", "defaultValue": "{{projectLocation}}"}, {"id": "project_name", "type": "text", "label": "Project Name", "readonly": true, "required": true, "defaultValue": "{{projectName}}"}, {"id": "duration", "type": "number", "label": "Duration (minutes)", "required": true, "validation": {"max": 240, "min": 5}, "defaultValue": 15}]}, {"id": "topic", "order": 2, "title": "Training Topic", "fields": [{"id": "topic", "type": "select", "label": "Primary Topic", "options": [{"label": "Fall Protection", "value": "fall_protection"}, {"label": "Electrical Safety", "value": "electrical_safety"}, {"label": "PPE Use", "value": "ppe_use"}, {"label": "Scaffolding Safety", "value": "scaffolding"}, {"label": "Ladder Safety", "value": "ladder_safety"}, {"label": "Excavation & Trenching", "value": "excavation_trenching"}, {"label": "Confined Spaces", "value": "confined_spaces"}, {"label": "Lockout/Tagout", "value": "lockout_tagout"}, {"label": "Crane & Rigging Safety", "value": "crane_rigging"}, {"label": "Heavy Equipment Safety", "value": "heavy_equipment"}, {"label": "Heat Stress Prevention", "value": "heat_stress"}, {"label": "Cold Stress Prevention", "value": "cold_stress"}, {"label": "Hazard Communication", "value": "hazard_communication"}, {"label": "Fire Prevention", "value": "fire_prevention"}, {"label": "Housekeeping & Cleanliness", "value": "housekeeping"}, {"label": "Hand & Power Tool Safety", "value": "hand_power_tools"}, {"label": "Material Handling", "value": "material_handling"}, {"label": "First Aid & Emergency Response", "value": "first_aid"}, {"label": "Struck-By Hazards", "value": "struck_by_hazards"}, {"label": "Caught-In/Between Hazards", "value": "caught_between"}, {"label": "Ergonomics & Lifting", "value": "ergonomics"}, {"label": "Concrete Operations", "value": "concrete_operations"}, {"label": "Demolition Safety", "value": "demolition"}, {"label": "Respiratory Protection", "value": "respiratory_protection"}, {"label": "Hearing Conservation", "value": "hearing_conservation"}, {"label": "Incident Investigation", "value": "incident_investigation"}, {"label": "New Worker Site Orientation", "value": "site_orientation"}, {"label": "Other (Specify)", "value": "other"}], "required": true}, {"id": "topic_other", "type": "text", "label": "Specify Other Topic", "required": true, "validation": {"maxLength": 150}, "conditionalDisplay": {"field": "topic", "value": "other", "operator": "equals"}}, {"id": "topic_description", "type": "textarea", "label": "Topic Description/Key Points Covered", "helpText": "Include main hazards discussed and safe work practices covered", "required": true, "validation": {"maxLength": 2000, "minLength": 20}, "placeholder": "Briefly describe the key safety points discussed..."}]}, {"id": "trainer", "order": 3, "title": "Trainer Information", "fields": [{"id": "trainer_name", "type": "text", "label": "Trainer/Presenter Name", "required": true, "validation": {"maxLength": 100}, "defaultValue": "{{currentUser}}"}, {"id": "trainer_title", "type": "text", "label": "Trainer Title/Position", "required": false, "validation": {"maxLength": 100}, "placeholder": "e.g., Safety Manager, Superintendent, Foreman"}, {"id": "trainer_company", "type": "text", "label": "Trainer Company", "required": false, "validation": {"maxLength": 150}, "defaultValue": "{{organizationName}}"}]}, {"id": "hazards", "order": 4, "title": "Hazards Discussed", "fields": [{"id": "specific_hazards", "type": "textarea", "label": "Specific Hazards for Today''s Work", "helpText": "Identify site-specific hazards relevant to current work activities", "required": false, "validation": {"maxLength": 1000}, "placeholder": "List specific hazards present on site today..."}, {"id": "control_measures", "type": "textarea", "label": "Control Measures/Safe Work Practices", "helpText": "What safety measures must workers follow?", "required": false, "validation": {"maxLength": 1000}, "placeholder": "Describe how to control or avoid the hazards..."}]}, {"id": "attendees", "order": 5, "title": "Attendee Sign-In", "fields": [{"id": "attendee_count", "type": "number", "label": "Number of Attendees", "computed": {"formula": "COUNT(attendees)"}, "readonly": true, "required": false}, {"id": "attendees", "type": "repeater", "label": "Attendees", "helpText": "All attendees must print name and sign", "maxItems": 100, "minItems": 1, "required": true, "itemSchema": {"fields": [{"id": "employee_name", "type": "text", "label": "Employee Name (Print)", "required": true, "validation": {"maxLength": 100}}, {"id": "company", "type": "text", "label": "Company", "required": false, "validation": {"maxLength": 100}, "defaultValue": "{{organizationName}}"}, {"id": "trade_position", "type": "text", "label": "Trade/Position", "required": false, "validation": {"maxLength": 75}, "placeholder": "e.g., Carpenter, Laborer, Operator"}, {"id": "signature", "type": "signature", "label": "Employee Signature", "helpText": "Sign to acknowledge attendance and understanding", "required": true, "captureTimestamp": true}]}}]}, {"id": "questions_feedback", "order": 6, "title": "Questions & Feedback", "fields": [{"id": "questions_asked", "type": "textarea", "label": "Questions Asked by Attendees", "required": false, "validation": {"maxLength": 1500}, "placeholder": "Document any questions raised and answers provided..."}, {"id": "employee_feedback", "type": "textarea", "label": "Employee Feedback/Concerns", "required": false, "validation": {"maxLength": 1000}, "placeholder": "Any additional safety concerns raised by workers..."}]}, {"id": "materials", "order": 7, "title": "Training Materials", "fields": [{"id": "handouts_provided", "type": "radio", "label": "Were handouts or materials provided?", "options": [{"label": "Yes", "value": "yes"}, {"label": "No", "value": "no"}], "required": true, "defaultValue": "no"}, {"id": "handout_description", "type": "text", "label": "Materials Description", "required": true, "validation": {"maxLength": 200}, "placeholder": "e.g., OSHA fact sheet, company SOP, manufacturer guidelines", "conditionalDisplay": {"field": "handouts_provided", "value": "yes", "operator": "equals"}}, {"id": "material_photos", "type": "photo", "label": "Photos of Materials/Whiteboard", "helpText": "Capture photos of whiteboard notes or handouts for record", "multiple": true, "required": false, "maxPhotos": 10, "captureGPS": false}]}, {"id": "signature", "order": 8, "title": "Trainer Certification", "fields": [{"id": "training_effective", "type": "select", "label": "Training Effectiveness", "options": [{"label": "Excellent - High engagement, clear understanding", "value": "excellent"}, {"label": "Good - Workers understood key points", "value": "good"}, {"label": "Fair - Some confusion, follow-up needed", "value": "fair"}, {"label": "Poor - Retraining required", "value": "poor"}], "required": true}, {"id": "follow_up_needed", "type": "radio", "label": "Is follow-up training needed?", "options": [{"label": "Yes", "value": "yes"}, {"label": "No", "value": "no"}], "required": true, "defaultValue": "no"}, {"id": "follow_up_notes", "type": "textarea", "label": "Follow-Up Training Notes", "required": true, "validation": {"maxLength": 500}, "placeholder": "Describe what follow-up training is needed and when...", "conditionalDisplay": {"field": "follow_up_needed", "value": "yes", "operator": "equals"}}, {"id": "notes", "type": "textarea", "label": "Additional Notes", "required": false, "validation": {"maxLength": 1000}, "placeholder": "Any additional comments about the training session..."}, {"id": "trainer_signature", "type": "signature", "label": "Trainer Signature", "helpText": "I certify this training was conducted and documented per OSHA requirements", "required": true, "captureTimestamp": true}]}]}', 'Initial system template from 04-toolbox-talk-sign-in.json', '2025-10-24 13:30:31.366', 'system');
INSERT INTO public.form_template_versions VALUES ('887c3a72-218f-4f36-b9fd-c5d996f39882', '7843e76f-5967-40f0-8098-4055711c092c', 1, '{"sections": [{"id": "report_info", "order": 1, "title": "Report Information", "fields": [{"id": "report_date", "type": "date", "label": "Report Date", "required": true, "validation": {"max": "{{currentDate}}"}, "defaultValue": "{{currentDate}}"}, {"id": "report_number", "type": "text", "label": "Report Number", "required": false, "validation": {"maxLength": 50}, "placeholder": "Auto-generated or manual entry"}, {"id": "prepared_by", "type": "text", "label": "Report Prepared By", "required": true, "validation": {"maxLength": 100}, "defaultValue": "{{currentUser}}"}]}, {"id": "employee_info", "order": 2, "title": "Employee Information (OSHA Form 301 Section 1)", "fields": [{"id": "employee_name", "type": "text", "label": "Employee Full Name", "helpText": "OSHA Form 301 Field 1", "required": true, "validation": {"maxLength": 150}}, {"id": "job_title", "type": "text", "label": "Job Title", "helpText": "OSHA Form 301 Field 3", "required": true, "validation": {"maxLength": 100}, "placeholder": "e.g., Carpenter, Laborer, Equipment Operator"}, {"id": "hire_date", "type": "date", "label": "Date Hired", "helpText": "OSHA Form 301 Field 2", "required": true, "validation": {"max": "{{currentDate}}"}}, {"id": "gender", "type": "select", "label": "Gender", "options": [{"label": "Male", "value": "male"}, {"label": "Female", "value": "female"}, {"label": "Decline to Answer", "value": "decline"}], "helpText": "Optional - for statistical purposes only", "required": false}]}, {"id": "incident_details", "order": 3, "title": "Incident Details (OSHA Form 301 Section 2)", "fields": [{"id": "incident_date", "type": "date", "label": "Date of Incident", "helpText": "OSHA Form 301 Field 4", "required": true, "validation": {"max": "{{currentDate}}"}}, {"id": "incident_time", "type": "time", "label": "Time of Incident", "helpText": "OSHA Form 301 Field 5", "required": true}, {"id": "time_began_work", "type": "time", "label": "Time Employee Began Work", "helpText": "What time did employee start their shift?", "required": false}, {"id": "location", "type": "text", "label": "Where Incident Occurred", "helpText": "OSHA Form 301 Field 6 - Be specific", "required": true, "validation": {"maxLength": 300}, "placeholder": "Specific location on site (e.g., 2nd floor east wing, parking lot)"}, {"id": "project_site", "type": "text", "label": "Project/Site Name", "required": true, "validation": {"maxLength": 200}, "defaultValue": "{{projectName}}"}]}, {"id": "what_happened", "order": 4, "title": "What Happened (OSHA Form 301 Section 3)", "fields": [{"id": "what_doing_before", "type": "textarea", "label": "What was employee doing just before incident occurred?", "helpText": "OSHA Form 301 Field 7", "required": true, "validation": {"maxLength": 1500, "minLength": 20}, "placeholder": "Describe the task/activity being performed..."}, {"id": "what_happened", "type": "textarea", "label": "What happened? How did the injury occur?", "helpText": "OSHA Form 301 Field 8 - Be detailed and specific", "required": true, "validation": {"maxLength": 2000, "minLength": 20}, "placeholder": "Describe the sequence of events that led to the injury..."}, {"id": "what_injury_illness", "type": "textarea", "label": "What was the injury or illness?", "helpText": "OSHA Form 301 Field 9", "required": true, "validation": {"maxLength": 500, "minLength": 10}, "placeholder": "e.g., Laceration, fracture, sprain, chemical burn, etc."}, {"id": "body_part", "type": "select", "label": "What part of body was affected?", "options": [{"label": "Head", "value": "head"}, {"label": "Eye(s)", "value": "eye"}, {"label": "Face", "value": "face"}, {"label": "Neck", "value": "neck"}, {"label": "Shoulder", "value": "shoulder"}, {"label": "Upper Arm", "value": "arm_upper"}, {"label": "Elbow", "value": "elbow"}, {"label": "Forearm", "value": "forearm"}, {"label": "Wrist", "value": "wrist"}, {"label": "Hand", "value": "hand"}, {"label": "Finger(s)", "value": "finger"}, {"label": "Chest", "value": "chest"}, {"label": "Upper Back", "value": "back_upper"}, {"label": "Lower Back", "value": "back_lower"}, {"label": "Abdomen", "value": "abdomen"}, {"label": "Hip", "value": "hip"}, {"label": "Upper Leg/Thigh", "value": "leg_upper"}, {"label": "Knee", "value": "knee"}, {"label": "Lower Leg", "value": "leg_lower"}, {"label": "Ankle", "value": "ankle"}, {"label": "Foot", "value": "foot"}, {"label": "Toe(s)", "value": "toe"}, {"label": "Multiple Parts", "value": "multiple"}, {"label": "Body System (internal)", "value": "body_systems"}], "helpText": "OSHA Form 301 Field 10", "required": true}, {"id": "body_part_detail", "type": "text", "label": "Body Part Details", "helpText": "Specify which side (left/right) and additional details", "required": false, "validation": {"maxLength": 150}, "placeholder": "e.g., Left index finger, Right knee, Both eyes"}, {"id": "object_substance", "type": "text", "label": "What object or substance directly harmed employee?", "helpText": "OSHA Form 301 Field 11 - What directly caused the harm?", "required": true, "validation": {"maxLength": 300}, "placeholder": "e.g., Concrete floor, power saw, chemicals, vehicle, etc."}]}, {"id": "treatment", "order": 5, "title": "Treatment & Outcome (OSHA Form 301 Section 4)", "fields": [{"id": "treatment_provided", "type": "select", "label": "Treatment Provided", "options": [{"label": "First Aid Only", "value": "first_aid"}, {"label": "Medical Treatment Beyond First Aid", "value": "medical_treatment"}, {"label": "Emergency Room Visit", "value": "emergency_room"}, {"label": "Hospitalized Overnight", "value": "hospitalized"}, {"label": "No Treatment Needed", "value": "none"}], "required": true}, {"id": "treatment_by_whom", "type": "text", "label": "Treatment Provided By", "helpText": "Who provided treatment?", "required": true, "validation": {"maxLength": 200}, "placeholder": "e.g., On-site first aid, Paramedics, Dr. Smith at XYZ Hospital"}, {"id": "physician_name", "type": "text", "label": "Physician or Health Care Professional Name", "helpText": "OSHA Form 301 Field 12", "required": false, "validation": {"maxLength": 150}, "placeholder": "Dr. Jane Doe"}, {"id": "facility_name", "type": "text", "label": "Health Facility Name", "helpText": "OSHA Form 301 Field 13 - If treated away from site", "required": false, "validation": {"maxLength": 200}, "placeholder": "e.g., City Medical Center, ABC Urgent Care"}, {"id": "emergency_room_visit", "type": "radio", "label": "Was employee treated in emergency room?", "options": [{"label": "Yes", "value": "yes"}, {"label": "No", "value": "no"}], "helpText": "OSHA Form 301 Field 14", "required": true, "defaultValue": "no"}, {"id": "hospitalized_overnight", "type": "radio", "label": "Was employee hospitalized overnight as in-patient?", "options": [{"label": "Yes", "value": "yes"}, {"label": "No", "value": "no"}], "helpText": "OSHA Form 301 Field 15", "required": true, "defaultValue": "no"}, {"id": "days_away_from_work", "type": "number", "label": "Days Away From Work", "helpText": "Number of days employee unable to work (0 if none)", "required": false, "validation": {"max": 365, "min": 0}}, {"id": "days_restricted_duty", "type": "number", "label": "Days on Restricted/Light Duty", "helpText": "Number of days on restricted/modified duty", "required": false, "validation": {"max": 365, "min": 0}}, {"id": "return_to_work_date", "type": "date", "label": "Actual Return to Work Date", "helpText": "When did employee return to full duty?", "required": false}]}, {"id": "witnesses", "order": 6, "title": "Witnesses & Investigation", "fields": [{"id": "witnesses", "type": "repeater", "label": "Witnesses", "maxItems": 15, "minItems": 0, "required": false, "itemSchema": {"fields": [{"id": "witness_name", "type": "text", "label": "Witness Name", "required": true, "validation": {"maxLength": 100}}, {"id": "witness_company", "type": "text", "label": "Company", "required": false, "validation": {"maxLength": 100}}, {"id": "witness_contact", "type": "text", "label": "Contact Info", "required": false, "validation": {"maxLength": 100}, "placeholder": "Phone or email"}, {"id": "statement", "type": "textarea", "label": "Witness Statement Summary", "required": false, "validation": {"maxLength": 1000}}]}}]}, {"id": "root_cause", "order": 7, "title": "Root Cause & Contributing Factors", "fields": [{"id": "immediate_cause", "type": "textarea", "label": "Immediate Cause of Incident", "required": false, "validation": {"maxLength": 1000}, "placeholder": "What directly caused the incident?"}, {"id": "root_cause", "type": "textarea", "label": "Root Cause Analysis", "required": false, "validation": {"maxLength": 1500}, "placeholder": "What underlying factors contributed? (procedures, training, equipment, etc.)"}, {"id": "contributing_factors", "type": "checkboxes", "label": "Contributing Factors (select all that apply)", "options": [{"label": "Inadequate Training", "value": "inadequate_training"}, {"label": "Lack of PPE", "value": "lack_of_ppe"}, {"label": "Equipment Failure", "value": "equipment_failure"}, {"label": "Unsafe Condition", "value": "unsafe_condition"}, {"label": "Unsafe Act", "value": "unsafe_act"}, {"label": "Poor Housekeeping", "value": "poor_housekeeping"}, {"label": "Inadequate Procedure", "value": "inadequate_procedure"}, {"label": "Time Pressure/Rushing", "value": "time_pressure"}, {"label": "Fatigue", "value": "fatigue"}, {"label": "Communication Failure", "value": "communication_failure"}, {"label": "Lack of Supervision", "value": "lack_of_supervision"}, {"label": "Environmental Factors (weather, lighting, etc.)", "value": "environmental"}], "required": false}]}, {"id": "corrective_actions", "order": 8, "title": "Corrective Actions", "fields": [{"id": "immediate_actions", "type": "textarea", "label": "Immediate Actions Taken", "required": true, "validation": {"maxLength": 1500, "minLength": 20}, "placeholder": "What actions were taken immediately after the incident?"}, {"id": "preventive_actions", "type": "repeater", "label": "Preventive/Corrective Actions", "helpText": "Actions to prevent recurrence", "maxItems": 15, "minItems": 1, "required": true, "itemSchema": {"fields": [{"id": "action", "type": "text", "label": "Corrective Action", "required": true, "validation": {"maxLength": 300}}, {"id": "responsible_person", "type": "text", "label": "Responsible Person", "required": true, "validation": {"maxLength": 100}}, {"id": "due_date", "type": "date", "label": "Due Date", "required": true}, {"id": "status", "type": "select", "label": "Status", "options": [{"label": "Pending", "value": "pending"}, {"label": "In Progress", "value": "in_progress"}, {"label": "Completed", "value": "completed"}], "required": true, "defaultValue": "pending"}, {"id": "completion_date", "type": "date", "label": "Completion Date", "required": false, "conditionalDisplay": {"field": "status", "value": "completed", "operator": "equals"}}]}}]}, {"id": "photos", "order": 9, "title": "Photo Documentation", "fields": [{"id": "incident_photos", "type": "photo", "label": "Incident Scene Photos", "helpText": "Document scene, equipment, conditions, and injuries (if appropriate)", "multiple": true, "required": false, "maxPhotos": 30, "captureGPS": true}]}, {"id": "classification", "order": 10, "title": "Incident Classification (For Internal Use)", "fields": [{"id": "recordable", "type": "select", "label": "OSHA Recordable?", "options": [{"label": "Yes - OSHA Recordable", "value": "yes"}, {"label": "No - First Aid Only", "value": "no"}, {"label": "Pending Determination", "value": "pending"}], "helpText": "Requires medical treatment beyond first aid, days away, restricted duty, or death", "required": true}, {"id": "severity", "type": "select", "label": "Incident Severity", "options": [{"label": "First Aid", "value": "first_aid"}, {"label": "Medical Treatment", "value": "medical_treatment"}, {"label": "Restricted Duty", "value": "restricted_duty"}, {"label": "Lost Time", "value": "lost_time"}, {"label": "Fatality", "value": "fatality"}], "required": true}, {"id": "reportable_to_osha", "type": "radio", "label": "Reportable to OSHA within 8/24 hours?", "options": [{"label": "Yes - Report immediately", "value": "yes"}, {"label": "No", "value": "no"}], "helpText": "Death, amputation, loss of eye, or in-patient hospitalization = 8 hrs. 3+ workers hospitalized = 24 hrs", "required": true, "defaultValue": "no"}]}, {"id": "signatures", "order": 11, "title": "Signatures & Approval", "fields": [{"id": "notes", "type": "textarea", "label": "Additional Notes/Comments", "required": false, "validation": {"maxLength": 2000}, "placeholder": "Any additional information relevant to this incident..."}, {"id": "supervisor_signature", "type": "signature", "label": "Supervisor Signature", "helpText": "Immediate supervisor or foreman", "required": true, "captureTimestamp": true}, {"id": "safety_manager_signature", "type": "signature", "label": "Safety Manager/Officer Signature", "helpText": "Review and approval by safety personnel", "required": false, "captureTimestamp": true}]}]}', 'Initial system template from 05-incident-report.json', '2025-10-24 13:30:31.377', 'system');
INSERT INTO public.form_template_versions VALUES ('42e4f734-2c00-4bf8-8d10-a5197d6c5103', '77b28e11-490c-44a7-bf2b-5136df0ca8c2', 1, '{"sections": [{"id": "inspection_info", "order": 1, "title": "Inspection Information", "fields": [{"id": "date", "type": "date", "label": "Inspection Date", "required": true, "validation": {"max": "{{currentDate}}"}, "defaultValue": "{{currentDate}}"}, {"id": "time", "type": "time", "label": "Inspection Time", "required": true, "defaultValue": "{{currentTime}}"}, {"id": "inspector_name", "type": "text", "label": "Inspector Name", "readonly": true, "required": true, "defaultValue": "{{currentUser}}"}, {"id": "inspector_company", "type": "text", "label": "Inspector Company", "required": false, "validation": {"maxLength": 150}, "defaultValue": "{{organizationName}}"}, {"id": "project_name", "type": "text", "label": "Project Name", "readonly": true, "required": true, "defaultValue": "{{projectName}}"}, {"id": "location", "type": "text", "label": "Inspection Location/Area", "required": true, "validation": {"maxLength": 200}, "placeholder": "e.g., Building A, 2nd Floor, Grid Lines A-D"}]}, {"id": "work_scope", "order": 2, "title": "Work Scope", "fields": [{"id": "work_type", "type": "select", "label": "Type of Work Being Inspected", "options": [{"label": "Formwork", "value": "formwork"}, {"label": "Rebar Placement", "value": "rebar_placement"}, {"label": "Concrete Work", "value": "concrete"}, {"label": "Masonry", "value": "masonry"}, {"label": "Structural Steel", "value": "steel_structural"}, {"label": "Wood Framing", "value": "framing_wood"}, {"label": "Metal Framing", "value": "framing_metal"}, {"label": "Roofing", "value": "roofing"}, {"label": "Siding/Exterior Cladding", "value": "siding"}, {"label": "Drywall", "value": "drywall"}, {"label": "Electrical", "value": "electrical"}, {"label": "Plumbing", "value": "plumbing"}, {"label": "HVAC", "value": "hvac"}, {"label": "Finishes (paint, flooring, etc.)", "value": "finishes"}, {"label": "Sitework/Grading", "value": "sitework"}, {"label": "Paving/Asphalt", "value": "paving"}, {"label": "Landscaping", "value": "landscaping"}, {"label": "Other", "value": "other"}], "required": true}, {"id": "work_type_other", "type": "text", "label": "Specify Other Work Type", "required": true, "validation": {"maxLength": 150}, "conditionalDisplay": {"field": "work_type", "value": "other", "operator": "equals"}}, {"id": "work_description", "type": "textarea", "label": "Work Description", "required": true, "validation": {"maxLength": 1000, "minLength": 10}, "placeholder": "Describe the specific work being inspected..."}, {"id": "contractor", "type": "text", "label": "Contractor/Subcontractor", "required": false, "validation": {"maxLength": 150}}, {"id": "specification_reference", "type": "text", "label": "Specification/Drawing Reference", "required": false, "validation": {"maxLength": 200}, "placeholder": "e.g., Drawing A-201, Spec Section 03300"}]}, {"id": "inspection_points", "order": 3, "title": "Inspection Points", "fields": [{"id": "workmanship", "type": "select", "label": "Workmanship Quality", "options": [{"label": "Excellent - Exceeds standards", "value": "excellent"}, {"label": "Acceptable - Meets standards", "value": "acceptable"}, {"label": "Marginal - Barely acceptable", "value": "marginal"}, {"label": "Unacceptable - Rework required", "value": "unacceptable"}, {"label": "N/A", "value": "not_applicable"}], "required": true}, {"id": "workmanship_notes", "type": "textarea", "label": "Workmanship Notes", "required": false, "validation": {"maxLength": 1000}, "placeholder": "Describe workmanship quality issues or observations..."}, {"id": "materials_compliance", "type": "select", "label": "Materials Compliance", "options": [{"label": "Compliant - Correct materials used", "value": "compliant"}, {"label": "Non-Compliant - Wrong materials", "value": "non_compliant"}, {"label": "Not Verified", "value": "not_verified"}, {"label": "N/A", "value": "not_applicable"}], "required": true}, {"id": "materials_notes", "type": "textarea", "label": "Materials Notes", "required": false, "validation": {"maxLength": 1000}, "placeholder": "Describe material issues or observations..."}, {"id": "dimensions_tolerances", "type": "select", "label": "Dimensions/Tolerances", "options": [{"label": "Within Tolerance", "value": "within_tolerance"}, {"label": "Out of Tolerance", "value": "out_of_tolerance"}, {"label": "Not Measured", "value": "not_measured"}, {"label": "N/A", "value": "not_applicable"}], "required": true}, {"id": "dimensions_notes", "type": "textarea", "label": "Dimensions/Tolerances Notes", "required": false, "validation": {"maxLength": 1000}, "placeholder": "Record measurements and deviations..."}, {"id": "code_compliance", "type": "select", "label": "Code Compliance", "options": [{"label": "Compliant - Meets code", "value": "compliant"}, {"label": "Non-Compliant - Code violation", "value": "non_compliant"}, {"label": "Not Assessed", "value": "not_assessed"}, {"label": "N/A", "value": "not_applicable"}], "required": true}, {"id": "code_notes", "type": "textarea", "label": "Code Compliance Notes", "required": false, "validation": {"maxLength": 1000}, "placeholder": "Note any code issues..."}]}, {"id": "custom_checklist", "order": 4, "title": "Inspection Checklist", "fields": [{"id": "checklist_items", "type": "repeater", "label": "Inspection Items", "helpText": "Add specific items to check for this type of work", "maxItems": 30, "minItems": 0, "required": false, "itemSchema": {"fields": [{"id": "item_description", "type": "text", "label": "Item Description", "required": true, "validation": {"maxLength": 200}, "placeholder": "e.g., Anchor bolt spacing, Level tolerance, Joint spacing"}, {"id": "result", "type": "select", "label": "Result", "options": [{"label": "Pass", "value": "pass"}, {"label": "Fail", "value": "fail"}, {"label": "N/A", "value": "na"}], "required": true}, {"id": "measurement", "type": "text", "label": "Measurement/Observation", "required": false, "validation": {"maxLength": 150}, "placeholder": "Actual measurement or observation"}, {"id": "required_value", "type": "text", "label": "Required Value/Tolerance", "required": false, "validation": {"maxLength": 150}, "placeholder": "Required specification or tolerance"}]}}]}, {"id": "deficiencies", "order": 5, "title": "Deficiencies", "fields": [{"id": "deficiencies_found", "type": "radio", "label": "Were deficiencies found?", "options": [{"label": "Yes", "value": "yes"}, {"label": "No", "value": "no"}], "required": true, "defaultValue": "no"}, {"id": "deficiency_list", "type": "repeater", "label": "Deficiencies", "maxItems": 30, "minItems": 1, "required": true, "itemSchema": {"fields": [{"id": "deficiency_description", "type": "textarea", "label": "Deficiency Description", "required": true, "validation": {"maxLength": 500, "minLength": 10}}, {"id": "location", "type": "text", "label": "Location", "required": false, "validation": {"maxLength": 150}, "placeholder": "Specific location of deficiency"}, {"id": "severity", "type": "select", "label": "Severity", "options": [{"label": "Critical - Stop work", "value": "critical"}, {"label": "Major - Must fix before proceeding", "value": "major"}, {"label": "Minor - Fix when convenient", "value": "minor"}], "required": true}, {"id": "corrective_action", "type": "text", "label": "Required Corrective Action", "required": true, "validation": {"maxLength": 300}}]}, "conditionalDisplay": {"field": "deficiencies_found", "value": "yes", "operator": "equals"}}]}, {"id": "overall_status", "order": 6, "title": "Overall Status & Re-Inspection", "fields": [{"id": "overall_result", "type": "select", "label": "Overall Inspection Result", "options": [{"label": "Approved - Work acceptable", "value": "approved"}, {"label": "Approved with Conditions - Minor fixes required", "value": "approved_with_conditions"}, {"label": "Rejected - Major rework required", "value": "rejected"}, {"label": "On Hold - Pending information/correction", "value": "on_hold"}], "required": true}, {"id": "reinspection_required", "type": "radio", "label": "Is re-inspection required?", "options": [{"label": "Yes", "value": "yes"}, {"label": "No", "value": "no"}], "required": true, "defaultValue": "no"}, {"id": "reinspection_date", "type": "date", "label": "Re-Inspection Due Date", "required": true, "conditionalDisplay": {"field": "reinspection_required", "value": "yes", "operator": "equals"}}, {"id": "reinspection_notes", "type": "textarea", "label": "Re-Inspection Notes", "required": false, "validation": {"maxLength": 1000}, "placeholder": "What needs to be verified at re-inspection?", "conditionalDisplay": {"field": "reinspection_required", "value": "yes", "operator": "equals"}}]}, {"id": "photos", "order": 7, "title": "Photo Documentation", "fields": [{"id": "inspection_photos", "type": "photo", "label": "Inspection Photos", "helpText": "Document work conditions, deficiencies, and compliance", "multiple": true, "required": false, "maxPhotos": 40, "captureGPS": true}]}, {"id": "signatures", "order": 8, "title": "Signatures & Acknowledgment", "fields": [{"id": "notes", "type": "textarea", "label": "Additional Notes/Comments", "required": false, "validation": {"maxLength": 2000}, "placeholder": "Any additional observations or recommendations..."}, {"id": "inspector_signature", "type": "signature", "label": "Inspector Signature", "required": true, "captureTimestamp": true}, {"id": "contractor_notified", "type": "radio", "label": "Contractor notified of deficiencies?", "options": [{"label": "Yes", "value": "yes"}, {"label": "No - No deficiencies", "value": "no"}, {"label": "Pending", "value": "pending"}], "required": true, "defaultValue": "pending"}, {"id": "contractor_acknowledgment", "type": "signature", "label": "Contractor Acknowledgment Signature", "helpText": "Contractor signature acknowledging inspection results", "required": false, "captureTimestamp": true}]}]}', 'Initial system template from 06-general-quality-inspection.json', '2025-10-24 13:30:31.388', 'system');
INSERT INTO public.form_template_versions VALUES ('9d2eeb0d-fbe2-40bb-8d8c-576b48adaeb4', '6ee6e0ee-31ce-40fa-9025-136387f2e06b', 1, '{"sections": [{"id": "project_info", "order": 1, "title": "Project Information", "fields": [{"id": "date", "type": "date", "label": "Pour Date", "required": true, "validation": {"max": "{{currentDate}}"}, "defaultValue": "{{currentDate}}"}, {"id": "project_name", "type": "text", "label": "Project Name", "readonly": true, "required": true, "defaultValue": "{{projectName}}"}, {"id": "element_location", "type": "text", "label": "Element/Location", "required": true, "validation": {"maxLength": 200}, "placeholder": "e.g., Foundation, Column Grid A-3, Slab Level 2"}, {"id": "inspector_name", "type": "text", "label": "Inspector Name", "readonly": true, "required": true, "defaultValue": "{{currentUser}}"}, {"id": "inspector_certification", "type": "text", "label": "Inspector Certification", "helpText": "ACI certification recommended", "required": false, "validation": {"maxLength": 150}, "placeholder": "e.g., ACI Field Testing Technician Grade I"}]}, {"id": "concrete_spec", "order": 2, "title": "Concrete Specification", "fields": [{"id": "mix_design", "type": "text", "label": "Mix Design Number", "required": true, "validation": {"maxLength": 100}}, {"id": "specified_strength", "type": "number", "label": "Specified Compressive Strength (psi)", "required": true, "validation": {"max": 15000, "min": 2000}, "placeholder": "e.g., 3000, 4000, 5000"}, {"id": "slump_spec", "type": "text", "label": "Specified Slump Range", "required": true, "validation": {"maxLength": 50}, "placeholder": "e.g., 4-6 inches, 75-125mm"}, {"id": "air_content_spec", "type": "text", "label": "Specified Air Content (%)", "required": false, "validation": {"maxLength": 50}, "placeholder": "e.g., 4-7%"}, {"id": "supplier", "type": "text", "label": "Concrete Supplier", "required": true, "validation": {"maxLength": 150}}]}, {"id": "pre_pour", "order": 3, "title": "Pre-Pour Inspection", "fields": [{"id": "formwork_condition", "type": "select", "label": "Formwork Condition", "options": [{"label": "Approved - Clean, tight, properly braced", "value": "approved"}, {"label": "Needs Correction", "value": "needs_correction"}, {"label": "Not Approved - Major issues", "value": "not_approved"}, {"label": "N/A", "value": "not_applicable"}], "required": true}, {"id": "formwork_alignment", "type": "select", "label": "Formwork Alignment/Stability", "options": [{"label": "Approved - Within tolerance", "value": "approved"}, {"label": "Needs Correction", "value": "needs_correction"}, {"label": "Not Approved", "value": "not_approved"}, {"label": "N/A", "value": "not_applicable"}], "required": true}, {"id": "formwork_cleanliness", "type": "select", "label": "Formwork Cleanliness", "options": [{"label": "Approved - Clean and debris-free", "value": "approved"}, {"label": "Needs Correction - Debris present", "value": "needs_correction"}, {"label": "Not Approved", "value": "not_approved"}], "required": true}, {"id": "rebar_placement", "type": "select", "label": "Rebar Placement/Spacing", "options": [{"label": "Approved - Per drawings", "value": "approved"}, {"label": "Needs Correction", "value": "needs_correction"}, {"label": "Not Approved", "value": "not_approved"}, {"label": "N/A - No rebar", "value": "not_applicable"}], "required": true}, {"id": "rebar_cover", "type": "select", "label": "Rebar Cover Thickness", "options": [{"label": "Approved - Adequate cover maintained", "value": "approved"}, {"label": "Needs Correction", "value": "needs_correction"}, {"label": "Not Approved - Insufficient cover", "value": "not_approved"}, {"label": "N/A", "value": "not_applicable"}], "required": true}, {"id": "embedments", "type": "select", "label": "Embedments/Inserts", "options": [{"label": "Approved - Properly located/secured", "value": "approved"}, {"label": "Needs Correction", "value": "needs_correction"}, {"label": "Not Approved", "value": "not_approved"}, {"label": "N/A", "value": "not_applicable"}], "required": true}, {"id": "weather_conditions", "type": "select", "label": "Weather Conditions", "options": [{"label": "Suitable for pouring", "value": "suitable"}, {"label": "Marginal - Precautions required", "value": "marginal"}, {"label": "Unsuitable - Should not pour", "value": "unsuitable"}], "required": true}, {"id": "temperature", "type": "number", "label": "Ambient Temperature (°F)", "helpText": "Critical for cold/hot weather concrete", "required": true, "validation": {"max": 150, "min": -20}}, {"id": "pre_pour_notes", "type": "textarea", "label": "Pre-Pour Notes", "required": false, "validation": {"maxLength": 1500}, "placeholder": "Document any pre-pour issues or observations..."}]}, {"id": "during_pour", "order": 4, "title": "During Pour Inspection", "fields": [{"id": "pour_start_time", "type": "time", "label": "Pour Start Time", "required": true}, {"id": "pour_end_time", "type": "time", "label": "Pour End Time", "required": true}, {"id": "slump_tests", "type": "repeater", "label": "Slump Tests", "helpText": "ACI requires slump test at point of placement", "maxItems": 10, "minItems": 1, "required": true, "itemSchema": {"fields": [{"id": "test_time", "type": "time", "label": "Test Time", "required": true}, {"id": "truck_number", "type": "text", "label": "Truck Number", "required": false, "validation": {"maxLength": 50}}, {"id": "slump_inches", "type": "number", "label": "Slump (inches)", "helpText": "Typical range: 4-6 inches", "required": true, "validation": {"max": 12, "min": 0, "precision": 0.25}}, {"id": "slump_acceptable", "type": "select", "label": "Within Spec?", "options": [{"label": "Yes - Within specification", "value": "yes"}, {"label": "No - Out of spec", "value": "no"}], "required": true}, {"id": "temperature_concrete", "type": "number", "label": "Concrete Temperature (°F)", "required": false, "validation": {"max": 150, "min": 0}}]}}, {"id": "air_content_test", "type": "number", "label": "Air Content Test (%)", "helpText": "Required for freeze-thaw exposure", "required": false, "validation": {"max": 15, "min": 0, "precision": 0.1}}, {"id": "placement_method", "type": "select", "label": "Placement Method", "options": [{"label": "Direct Chute", "value": "direct_chute"}, {"label": "Concrete Pump", "value": "pump"}, {"label": "Crane/Bucket", "value": "bucket"}, {"label": "Wheelbarrow/Buggy", "value": "wheelbarrow"}, {"label": "Conveyor Belt", "value": "conveyor"}], "required": true}, {"id": "consolidation_method", "type": "select", "label": "Consolidation Method", "options": [{"label": "Internal Vibrator", "value": "internal_vibrator"}, {"label": "External Vibrator (form)", "value": "external_vibrator"}, {"label": "Self-Consolidating Concrete", "value": "self_consolidating"}, {"label": "Hand Tools Only", "value": "hand_tools"}], "required": true}, {"id": "free_fall_limit", "type": "select", "label": "Free Fall Limit (<1 meter per ACI)", "options": [{"label": "Compliant - Free fall <1 meter", "value": "compliant"}, {"label": "Non-Compliant - Excessive free fall", "value": "non_compliant"}], "helpText": "ACI 318 limits free fall to prevent segregation", "required": true}, {"id": "layer_thickness", "type": "select", "label": "Layer Thickness (<450mm per ACI)", "options": [{"label": "Compliant - Layers <450mm", "value": "compliant"}, {"label": "Non-Compliant - Excessive thickness", "value": "non_compliant"}, {"label": "N/A - Single lift", "value": "not_applicable"}], "helpText": "ACI recommends max 450mm layer thickness", "required": true}, {"id": "cold_joints", "type": "select", "label": "Cold Joints/Delays", "options": [{"label": "No delays - Continuous pour", "value": "no_delays"}, {"label": "Short delay - Within initial set time", "value": "acceptable_delay"}, {"label": "Cold joint formed - Exceeded initial set", "value": "cold_joint"}], "helpText": "Continuous pour preferred per ACI", "required": true}, {"id": "during_pour_notes", "type": "textarea", "label": "During Pour Notes", "required": false, "validation": {"maxLength": 1500}, "placeholder": "Document placement issues, delays, or observations..."}]}, {"id": "test_cylinders", "order": 5, "title": "Test Cylinder Samples", "fields": [{"id": "cylinder_sets", "type": "repeater", "label": "Test Cylinder Sets", "helpText": "ACI requires minimum 2 cylinders per set for compressive strength testing", "maxItems": 10, "minItems": 1, "required": true, "itemSchema": {"fields": [{"id": "set_number", "type": "text", "label": "Set/Sample ID", "required": true, "validation": {"maxLength": 50}}, {"id": "sample_time", "type": "time", "label": "Sample Time", "required": true}, {"id": "truck_number", "type": "text", "label": "Truck Number", "required": false, "validation": {"maxLength": 50}}, {"id": "cylinders_made", "type": "number", "label": "Number of Cylinders", "helpText": "Minimum 2 per set per ACI", "required": true, "validation": {"max": 10, "min": 2}}, {"id": "test_ages", "type": "text", "label": "Test Ages (days)", "helpText": "Common: 7 days, 28 days", "required": true, "validation": {"maxLength": 100}, "placeholder": "e.g., 7, 28"}, {"id": "location_represented", "type": "text", "label": "Location Represented", "required": false, "validation": {"maxLength": 150}, "placeholder": "Which area of pour this sample represents"}]}}, {"id": "total_cubic_yards", "type": "number", "label": "Total Concrete Volume (cubic yards)", "required": true, "validation": {"max": 10000, "min": 0, "precision": 0.25}}, {"id": "testing_lab", "type": "text", "label": "Testing Laboratory", "required": false, "validation": {"maxLength": 150}}]}, {"id": "post_pour", "order": 6, "title": "Post-Pour Inspection", "fields": [{"id": "finishing_method", "type": "select", "label": "Surface Finishing Method", "options": [{"label": "Trowel - Smooth Finish", "value": "trowel_smooth"}, {"label": "Trowel - Rough Finish", "value": "trowel_rough"}, {"label": "Broom Finish", "value": "broom"}, {"label": "Float Finish", "value": "float"}, {"label": "As-Placed (no finish)", "value": "as_placed"}, {"label": "Other", "value": "other"}], "required": true}, {"id": "surface_quality", "type": "select", "label": "Surface Finish Quality", "options": [{"label": "Excellent", "value": "excellent"}, {"label": "Acceptable", "value": "acceptable"}, {"label": "Marginal", "value": "marginal"}, {"label": "Unacceptable - Rework required", "value": "unacceptable"}], "required": true}, {"id": "curing_method", "type": "select", "label": "Curing Method", "options": [{"label": "Wet Burlap/Blankets", "value": "wet_burlap"}, {"label": "Curing Compound", "value": "curing_compound"}, {"label": "Plastic Sheeting", "value": "plastic_sheeting"}, {"label": "Water Ponding", "value": "water_ponding"}, {"label": "Fog/Mist Spray", "value": "fog_spray"}, {"label": "Forms Left in Place", "value": "forms_left_on"}, {"label": "None - Explain in notes", "value": "none"}], "required": true}, {"id": "curing_start_time", "type": "time", "label": "Curing Started", "helpText": "When was curing initiated?", "required": false}, {"id": "geometry_check", "type": "select", "label": "Geometry Verification (dimensions, alignment)", "options": [{"label": "Approved - Within tolerance", "value": "approved"}, {"label": "Needs Correction", "value": "needs_correction"}, {"label": "Not Approved", "value": "not_approved"}, {"label": "Not Measured - Will verify after stripping", "value": "not_measured"}], "required": true}, {"id": "surface_defects", "type": "checkboxes", "label": "Surface Defects (select all that apply)", "options": [{"label": "None", "value": "none"}, {"label": "Honeycomb", "value": "honeycomb"}, {"label": "Segregation", "value": "segregation"}, {"label": "Cracks", "value": "cracks"}, {"label": "Spalling", "value": "spalling"}, {"label": "Discoloration", "value": "discoloration"}, {"label": "Voids/Bug Holes", "value": "voids"}, {"label": "Formwork Defects (tie holes, offsets)", "value": "formwork_defects"}], "required": false}, {"id": "defect_locations", "type": "textarea", "label": "Defect Locations/Descriptions", "required": false, "validation": {"maxLength": 1500}, "placeholder": "Describe location and extent of any defects..."}, {"id": "post_pour_notes", "type": "textarea", "label": "Post-Pour Notes", "required": false, "validation": {"maxLength": 1500}, "placeholder": "Any additional observations..."}]}, {"id": "photos", "order": 7, "title": "Photo Documentation", "fields": [{"id": "pour_photos", "type": "photo", "label": "Pour Documentation Photos", "helpText": "Document: formwork, rebar, slump test, placement, finish, defects", "multiple": true, "required": false, "maxPhotos": 40, "captureGPS": true}]}, {"id": "signature", "order": 8, "title": "Inspector Certification", "fields": [{"id": "overall_approval", "type": "select", "label": "Overall Pour Approval", "options": [{"label": "Approved - Meets ACI standards", "value": "approved"}, {"label": "Approved with Conditions - Minor issues noted", "value": "approved_with_conditions"}, {"label": "Rejected - Major defects/non-compliance", "value": "rejected"}], "required": true}, {"id": "notes", "type": "textarea", "label": "Final Notes/Recommendations", "required": false, "validation": {"maxLength": 2000}, "placeholder": "Any final observations or recommendations..."}, {"id": "inspector_signature", "type": "signature", "label": "Inspector Signature", "helpText": "I certify this inspection was conducted per ACI 318 standards", "required": true, "captureTimestamp": true}, {"id": "contractor_acknowledgment", "type": "signature", "label": "Contractor Acknowledgment", "required": false, "captureTimestamp": true}]}]}', 'Initial system template from 07-concrete-pour-inspection.json', '2025-10-24 13:30:31.398', 'system');
INSERT INTO public.form_template_versions VALUES ('0b9f1b32-0a51-47c9-b368-ab88eb9c7e6f', '3effdae7-b21f-42cd-b7a5-b12334c74e40', 1, '{"sections": [{"id": "inspection_info", "order": 1, "title": "Inspection Information", "fields": [{"id": "date", "type": "date", "label": "Inspection Date", "required": true, "defaultValue": "{{currentDate}}"}, {"id": "shift", "type": "select", "label": "Shift", "options": [{"label": "Day Shift", "value": "day"}, {"label": "Night Shift", "value": "night"}, {"label": "Swing Shift", "value": "swing"}], "required": true}, {"id": "inspector_name", "type": "text", "label": "Inspector Name", "required": true, "defaultValue": "{{currentUser}}"}, {"id": "inspector_title", "type": "text", "label": "Inspector Title", "required": false, "placeholder": "Competent Person, Foreman, Safety Manager"}]}, {"id": "equipment_info", "order": 2, "title": "Equipment Information", "fields": [{"id": "equipment_type", "type": "select", "label": "Equipment Type", "options": [{"label": "Excavator", "value": "excavator"}, {"label": "Loader", "value": "loader"}, {"label": "Dozer", "value": "dozer"}, {"label": "Backhoe", "value": "backhoe"}, {"label": "Crane", "value": "crane"}, {"label": "Forklift", "value": "forklift"}, {"label": "Scissor Lift", "value": "scissor_lift"}, {"label": "Boom Lift", "value": "boom_lift"}, {"label": "Skid Steer", "value": "skid_steer"}, {"label": "Compactor", "value": "compactor"}, {"label": "Dump Truck", "value": "dump_truck"}, {"label": "Concrete Pump", "value": "concrete_pump"}, {"label": "Generator", "value": "generator"}, {"label": "Other", "value": "other"}], "required": true}, {"id": "equipment_id", "type": "text", "label": "Equipment ID/Number", "required": true, "validation": {"maxLength": 100}}, {"id": "make_model", "type": "text", "label": "Make/Model", "required": false}, {"id": "operator_name", "type": "text", "label": "Operator Name", "required": false}, {"id": "hour_meter", "type": "number", "label": "Hour Meter Reading", "required": false, "validation": {"max": 99999, "min": 0}}]}, {"id": "walk_around", "order": 3, "title": "Walk-Around Check", "fields": [{"id": "tires_tracks", "type": "select", "label": "Tires/Tracks Condition", "options": [{"label": "Good - Proper inflation/tension", "value": "good"}, {"label": "Fair - Acceptable", "value": "fair"}, {"label": "Poor - Needs attention", "value": "poor"}, {"label": "N/A", "value": "na"}], "required": true}, {"id": "fluid_levels", "type": "select", "label": "Fluid Levels (oil, hydraulic, coolant)", "options": [{"label": "Good - All levels adequate", "value": "good"}, {"label": "Low - Top-off required", "value": "low"}, {"label": "Critical - Do not operate", "value": "critical"}], "required": true}, {"id": "leaks", "type": "select", "label": "Leaks (hydraulic, fuel, oil)", "options": [{"label": "No leaks", "value": "none"}, {"label": "Minor leak - Monitor", "value": "minor"}, {"label": "Major leak - Repair required", "value": "major"}], "required": true}, {"id": "bolts_pins", "type": "select", "label": "Bolts/Pins Secure", "options": [{"label": "All secure", "value": "secure"}, {"label": "Loose - Tighten required", "value": "loose"}, {"label": "Missing - Do not operate", "value": "missing"}], "required": true}, {"id": "structural_damage", "type": "select", "label": "Structural Damage", "options": [{"label": "No damage", "value": "none"}, {"label": "Minor damage - Document", "value": "minor"}, {"label": "Major damage - Out of service", "value": "major"}], "required": true}, {"id": "guards_shields", "type": "select", "label": "Guards/Shields in Place", "options": [{"label": "All installed", "value": "installed"}, {"label": "Missing - Do not operate", "value": "missing"}], "required": true}]}, {"id": "safety_features", "order": 4, "title": "Safety Features", "fields": [{"id": "brakes", "type": "select", "label": "Brakes Functioning", "options": [{"label": "Good - Responsive", "value": "good"}, {"label": "Marginal - Needs adjustment", "value": "marginal"}, {"label": "Failed - Out of service", "value": "failed"}], "required": true}, {"id": "steering", "type": "select", "label": "Steering Controls", "options": [{"label": "Good - Responsive", "value": "good"}, {"label": "Stiff - Needs service", "value": "stiff"}, {"label": "Failed", "value": "failed"}], "required": true}, {"id": "hydraulics", "type": "select", "label": "Hydraulic Systems", "options": [{"label": "Good - All functions work", "value": "good"}, {"label": "Sluggish - Check fluid/filter", "value": "sluggish"}, {"label": "Failed - Out of service", "value": "failed"}, {"label": "N/A", "value": "na"}], "required": true}, {"id": "emergency_stop", "type": "select", "label": "Emergency Stop/Shutdown", "options": [{"label": "Functional - Tested", "value": "functional"}, {"label": "Not tested", "value": "not_tested"}, {"label": "Failed - Do not operate", "value": "failed"}, {"label": "N/A", "value": "na"}], "required": true}, {"id": "horn", "type": "select", "label": "Horn/Backup Alarm", "options": [{"label": "Functional", "value": "functional"}, {"label": "Weak - Replace", "value": "weak"}, {"label": "Inoperative - Repair required", "value": "inoperative"}], "required": true}, {"id": "seatbelt", "type": "select", "label": "Seatbelt", "options": [{"label": "Good condition", "value": "good"}, {"label": "Worn - Replace", "value": "worn"}, {"label": "Missing - Do not operate", "value": "missing"}], "required": true}, {"id": "fire_extinguisher", "type": "select", "label": "Fire Extinguisher", "options": [{"label": "Present & Charged", "value": "present_charged"}, {"label": "Present but discharged", "value": "present_discharged"}, {"label": "Missing", "value": "missing"}], "required": true}, {"id": "lights", "type": "select", "label": "Lights (if applicable)", "options": [{"label": "All functional", "value": "functional"}, {"label": "Some inoperative", "value": "some_out"}, {"label": "All inoperative", "value": "all_out"}, {"label": "N/A - Daylight only", "value": "na"}], "required": true}, {"id": "rops_fops", "type": "select", "label": "ROPS/FOPS (Rollover/Falling Object Protection)", "options": [{"label": "Intact - No damage", "value": "intact"}, {"label": "Damaged - Do not operate", "value": "damaged"}, {"label": "Removed - VIOLATION", "value": "removed"}, {"label": "N/A", "value": "na"}], "required": true}]}, {"id": "deficiencies", "order": 5, "title": "Deficiencies & Corrective Actions", "fields": [{"id": "deficiencies_found", "type": "radio", "label": "Deficiencies Found?", "options": [{"label": "Yes", "value": "yes"}, {"label": "No", "value": "no"}], "required": true, "defaultValue": "no"}, {"id": "deficiency_list", "type": "repeater", "label": "Deficiencies", "maxItems": 20, "minItems": 1, "required": true, "itemSchema": {"fields": [{"id": "issue", "type": "text", "label": "Issue Description", "required": true}, {"id": "severity", "type": "select", "label": "Severity", "options": [{"label": "Critical - Do not operate", "value": "critical"}, {"label": "High - Repair before next shift", "value": "high"}, {"label": "Medium - Repair this week", "value": "medium"}, {"label": "Low - Monitor", "value": "low"}], "required": true}, {"id": "corrective_action", "type": "text", "label": "Corrective Action", "required": true}]}, "conditionalDisplay": {"field": "deficiencies_found", "value": "yes", "operator": "equals"}}]}, {"id": "equipment_status", "order": 6, "title": "Equipment Status", "fields": [{"id": "status", "type": "select", "label": "Equipment Status", "options": [{"label": "APPROVED - Safe to operate", "value": "approved"}, {"label": "APPROVED WITH CONDITIONS - Minor issues noted", "value": "approved_with_conditions"}, {"label": "OUT OF SERVICE - Do not operate", "value": "out_of_service"}], "required": true}, {"id": "out_of_service_reason", "type": "textarea", "label": "Out of Service Reason", "required": true, "conditionalDisplay": {"field": "status", "value": "out_of_service", "operator": "equals"}}, {"id": "photos", "type": "photo", "label": "Inspection Photos", "helpText": "Document deficiencies or equipment condition", "multiple": true, "required": false, "maxPhotos": 20, "captureGPS": true}]}, {"id": "signature", "order": 7, "title": "Inspector Certification", "fields": [{"id": "notes", "type": "textarea", "label": "Additional Notes", "required": false, "validation": {"maxLength": 1000}}, {"id": "inspector_signature", "type": "signature", "label": "Inspector Signature", "helpText": "I certify this inspection was conducted per OSHA 1926.1412", "required": true, "captureTimestamp": true}, {"id": "operator_acknowledgment", "type": "signature", "label": "Operator Acknowledgment", "helpText": "Operator acknowledges equipment status", "required": false, "captureTimestamp": true}]}]}', 'Initial system template from 08-daily-equipment-inspection.json', '2025-10-24 13:30:31.408', 'system');
INSERT INTO public.form_template_versions VALUES ('d946bf78-1376-44a7-9202-faf970758b34', 'e3e5337e-1d3c-4285-a7fa-9c2a7725e6e4', 1, '{"sections": [{"id": "delivery_info", "order": 1, "title": "Delivery Information", "fields": [{"id": "date", "type": "date", "label": "Delivery Date", "required": true, "defaultValue": "{{currentDate}}"}, {"id": "time", "type": "time", "label": "Delivery Time", "required": true, "defaultValue": "{{currentTime}}"}, {"id": "project_name", "type": "text", "label": "Project Name", "readonly": true, "required": true, "defaultValue": "{{projectName}}"}, {"id": "delivery_location", "type": "text", "label": "Delivery Location on Site", "required": true, "placeholder": "e.g., Lay down yard, Building A entrance"}]}, {"id": "supplier_info", "order": 2, "title": "Supplier Information", "fields": [{"id": "supplier_name", "type": "text", "label": "Supplier/Vendor Name", "required": true, "validation": {"maxLength": 200}}, {"id": "supplier_contact", "type": "text", "label": "Supplier Contact/Phone", "required": false, "validation": {"maxLength": 100}}, {"id": "driver_name", "type": "text", "label": "Delivery Driver Name", "required": false, "validation": {"maxLength": 100}}, {"id": "truck_number", "type": "text", "label": "Truck/Vehicle Number", "required": false, "validation": {"maxLength": 50}}, {"id": "delivery_ticket_number", "type": "text", "label": "Delivery Ticket/BOL Number", "helpText": "Bill of Lading or delivery ticket reference", "required": false, "validation": {"maxLength": 100}}]}, {"id": "purchase_order", "order": 3, "title": "Purchase Order", "fields": [{"id": "po_number", "type": "text", "label": "Purchase Order Number", "required": false, "validation": {"maxLength": 100}}, {"id": "po_line_item", "type": "text", "label": "PO Line Item", "required": false, "validation": {"maxLength": 50}}, {"id": "requisition_number", "type": "text", "label": "Requisition Number", "required": false, "validation": {"maxLength": 100}}]}, {"id": "items", "order": 4, "title": "Items Delivered", "fields": [{"id": "delivery_items", "type": "repeater", "label": "Items", "maxItems": 50, "minItems": 1, "required": true, "itemSchema": {"fields": [{"id": "description", "type": "text", "label": "Item Description", "required": true, "validation": {"maxLength": 300}, "placeholder": "e.g., Rebar #5, 20ft lengths; Plywood 3/4\" 4x8 sheets"}, {"id": "quantity_ordered", "type": "number", "label": "Quantity Ordered", "helpText": "Expected quantity per PO", "required": false, "validation": {"max": 999999, "min": 0}}, {"id": "quantity_delivered", "type": "number", "label": "Quantity Delivered", "required": true, "validation": {"max": 999999, "min": 0}}, {"id": "unit", "type": "select", "label": "Unit of Measure", "options": [{"label": "Each (ea)", "value": "each"}, {"label": "Pieces (pcs)", "value": "pieces"}, {"label": "Boxes", "value": "boxes"}, {"label": "Pallets", "value": "pallets"}, {"label": "Cubic Yards (CY)", "value": "cubic_yards"}, {"label": "Square Feet (SF)", "value": "square_feet"}, {"label": "Linear Feet (LF)", "value": "linear_feet"}, {"label": "Tons", "value": "tons"}, {"label": "Pounds (lbs)", "value": "pounds"}, {"label": "Gallons", "value": "gallons"}, {"label": "Rolls", "value": "rolls"}, {"label": "Bundles", "value": "bundles"}, {"label": "Other", "value": "other"}], "required": true}, {"id": "unit_other", "type": "text", "label": "Specify Unit", "required": true, "conditionalDisplay": {"field": "unit", "value": "other", "operator": "equals"}}, {"id": "condition", "type": "select", "label": "Condition Upon Receipt", "options": [{"label": "Good - No damage", "value": "good"}, {"label": "Fair - Minor issues", "value": "fair"}, {"label": "Damaged", "value": "damaged"}, {"label": "Incorrect item", "value": "incorrect"}], "required": true}, {"id": "damage_description", "type": "textarea", "label": "Damage/Issue Description", "required": true, "validation": {"maxLength": 500}, "conditionalDisplay": {"field": "condition", "value": ["fair", "damaged", "incorrect"], "operator": "in"}}]}}]}, {"id": "discrepancies", "order": 5, "title": "Discrepancies", "fields": [{"id": "discrepancies_found", "type": "radio", "label": "Were there any discrepancies?", "options": [{"label": "Yes", "value": "yes"}, {"label": "No - Delivery matches PO", "value": "no"}], "required": true, "defaultValue": "no"}, {"id": "discrepancy_type", "type": "checkboxes", "label": "Discrepancy Type (select all that apply)", "options": [{"label": "Short Shipment - Less than ordered", "value": "short_shipment"}, {"label": "Over Shipment - More than ordered", "value": "over_shipment"}, {"label": "Wrong Item - Incorrect material", "value": "wrong_item"}, {"label": "Damaged - Physical damage", "value": "damaged"}, {"label": "Missing Documentation (certs, test reports)", "value": "missing_docs"}, {"label": "Late Delivery", "value": "late_delivery"}], "required": true, "conditionalDisplay": {"field": "discrepancies_found", "value": "yes", "operator": "equals"}}, {"id": "discrepancy_notes", "type": "textarea", "label": "Discrepancy Details", "required": true, "validation": {"maxLength": 1500}, "placeholder": "Describe the discrepancies and actions taken...", "conditionalDisplay": {"field": "discrepancies_found", "value": "yes", "operator": "equals"}}, {"id": "supplier_notified", "type": "radio", "label": "Supplier Notified of Discrepancy?", "options": [{"label": "Yes", "value": "yes"}, {"label": "No", "value": "no"}], "required": true, "conditionalDisplay": {"field": "discrepancies_found", "value": "yes", "operator": "equals"}}]}, {"id": "photos", "order": 6, "title": "Photo Documentation", "fields": [{"id": "delivery_photos", "type": "photo", "label": "Delivery Photos", "helpText": "Document materials, equipment, damage, or discrepancies", "multiple": true, "required": false, "maxPhotos": 30, "captureGPS": true}]}, {"id": "special_handling", "order": 7, "title": "Special Handling/Notes", "fields": [{"id": "storage_location", "type": "text", "label": "Storage Location Assigned", "required": false, "validation": {"maxLength": 200}, "placeholder": "Where materials were placed/stored"}, {"id": "certifications_received", "type": "radio", "label": "Certifications/Test Reports Received?", "options": [{"label": "Yes", "value": "yes"}, {"label": "No", "value": "no"}, {"label": "N/A", "value": "na"}], "helpText": "Mill certs, test reports, material certifications", "required": false}, {"id": "special_instructions", "type": "textarea", "label": "Special Handling Instructions/Notes", "required": false, "validation": {"maxLength": 1000}, "placeholder": "Any special storage, handling, or usage requirements..."}]}, {"id": "signatures", "order": 8, "title": "Signatures & Acknowledgment", "fields": [{"id": "notes", "type": "textarea", "label": "Additional Notes", "required": false, "validation": {"maxLength": 1000}, "placeholder": "Any additional information about the delivery..."}, {"id": "receiver_name", "type": "text", "label": "Receiver Name", "readonly": true, "required": true, "defaultValue": "{{currentUser}}"}, {"id": "receiver_title", "type": "text", "label": "Receiver Title/Position", "required": false, "validation": {"maxLength": 100}, "placeholder": "e.g., Foreman, Project Manager, Warehouse Lead"}, {"id": "receiver_signature", "type": "signature", "label": "Receiver Signature", "helpText": "I acknowledge receipt of the above materials/equipment", "required": true, "captureTimestamp": true}, {"id": "driver_signature", "type": "signature", "label": "Driver Signature", "helpText": "Driver acknowledges delivery completed", "required": false, "captureTimestamp": true}]}]}', 'Initial system template from 09-equipment-material-delivery-receipt.json', '2025-10-24 13:30:31.417', 'system');
INSERT INTO public.form_template_versions VALUES ('6613e07a-b8b0-4922-87d9-f07598c73c14', '65824058-9a10-4e36-8fba-4d8991e0f00b', 1, '{"sections": [{"id": "inspection_info", "order": 1, "title": "Inspection Information", "fields": [{"id": "inspection_type", "type": "select", "label": "Inspection Type", "options": [{"label": "7-Day Routine Inspection", "value": "7_day_routine"}, {"label": "Post-Storm Inspection (≥0.25\" rain)", "value": "post_storm"}], "helpText": "EPA CGP requires BOTH types", "required": true}, {"id": "inspection_date", "type": "date", "label": "Inspection Date", "required": true, "defaultValue": "{{currentDate}}"}, {"id": "inspection_time", "type": "time", "label": "Inspection Time", "required": true, "defaultValue": "{{currentTime}}"}, {"id": "inspector_name", "type": "text", "label": "Inspector Name", "required": true, "defaultValue": "{{currentUser}}"}, {"id": "inspector_qualifications", "type": "text", "label": "Inspector Qualifications", "helpText": "EPA requires qualified personnel", "required": false, "placeholder": "e.g., CPESC, Qualified SWPPP Practitioner"}, {"id": "project_name", "type": "text", "label": "Project Name", "readonly": true, "required": true, "defaultValue": "{{projectName}}"}]}, {"id": "storm_event", "order": 2, "title": "Storm Event Information (Post-Storm Only)", "fields": [{"id": "storm_date", "type": "date", "label": "Storm Date", "required": true, "conditionalDisplay": {"field": "inspection_type", "value": "post_storm", "operator": "equals"}}, {"id": "storm_end_time", "type": "time", "label": "Storm End Time", "required": false, "conditionalDisplay": {"field": "inspection_type", "value": "post_storm", "operator": "equals"}}, {"id": "rain_amount", "type": "number", "label": "Total Rainfall (inches)", "helpText": "EXACT 0.25 inches triggers inspection per EPA CGP 2022 Section 4.4", "required": true, "validation": {"max": 20, "min": 0.25, "precision": 0.01}, "conditionalDisplay": {"field": "inspection_type", "value": "post_storm", "operator": "equals"}}, {"id": "accumulation_period", "type": "text", "label": "Accumulation Period", "helpText": "Multiple storms totaling ≥0.25\" in 24-hour window = one inspection", "required": false, "placeholder": "e.g., Single storm or multiple storms within 24 hours", "conditionalDisplay": {"field": "inspection_type", "value": "post_storm", "operator": "equals"}}, {"id": "inspection_deadline", "type": "datetime-local", "label": "Inspection Deadline (24 hours working hours)", "helpText": "If storm Friday, inspection due Monday next work day", "required": false, "conditionalDisplay": {"field": "inspection_type", "value": "post_storm", "operator": "equals"}}]}, {"id": "weather_current", "order": 3, "title": "Current Weather Conditions", "fields": [{"id": "weather_conditions", "type": "select", "label": "Weather During Inspection", "options": [{"label": "Clear", "value": "clear"}, {"label": "Cloudy", "value": "cloudy"}, {"label": "Raining", "value": "rain"}, {"label": "Snowing", "value": "snow"}], "required": true}, {"id": "temperature", "type": "number", "label": "Temperature (°F)", "required": false, "validation": {"max": 150, "min": -20}}, {"id": "recent_precipitation", "type": "textarea", "label": "Recent Precipitation Notes", "required": false, "validation": {"maxLength": 500}, "placeholder": "Describe recent weather impacts on site..."}]}, {"id": "bmp_inspection", "order": 4, "title": "Best Management Practices (BMP) Inspection", "fields": [{"id": "silt_fences", "type": "select", "label": "Silt Fences", "options": [{"label": "Good - Intact, minimal sediment", "value": "good"}, {"label": "Fair - Needs maintenance", "value": "fair"}, {"label": "Poor - Damaged/ineffective", "value": "poor"}, {"label": "N/A", "value": "na"}], "required": true}, {"id": "silt_fence_notes", "type": "text", "label": "Silt Fence Notes", "helpText": "Location and condition details", "required": false, "validation": {"maxLength": 200}}, {"id": "inlet_protection", "type": "select", "label": "Inlet Protection", "options": [{"label": "Good - Clean, functioning", "value": "good"}, {"label": "Fair - Needs cleaning", "value": "fair"}, {"label": "Poor - Clogged/damaged", "value": "poor"}, {"label": "N/A", "value": "na"}], "required": true}, {"id": "stabilized_entrance", "type": "select", "label": "Stabilized Construction Entrance", "options": [{"label": "Good - Clean, functional", "value": "good"}, {"label": "Fair - Needs rock added", "value": "fair"}, {"label": "Poor - Mud tracking observed", "value": "poor"}, {"label": "N/A", "value": "na"}], "required": true}, {"id": "storm_drain_covers", "type": "select", "label": "Storm Drain Covers/Filters", "options": [{"label": "Good - In place, secure", "value": "good"}, {"label": "Fair - Needs adjustment", "value": "fair"}, {"label": "Poor - Missing/displaced", "value": "poor"}, {"label": "N/A", "value": "na"}], "required": true}, {"id": "sediment_basins", "type": "select", "label": "Sediment Basins/Traps", "options": [{"label": "Good - Adequate capacity", "value": "good"}, {"label": "Fair - Needs cleaning", "value": "fair"}, {"label": "Poor - At capacity, ineffective", "value": "poor"}, {"label": "N/A", "value": "na"}], "required": true}, {"id": "erosion_control_blankets", "type": "select", "label": "Erosion Control Blankets/Mats", "options": [{"label": "Good - Secured, intact", "value": "good"}, {"label": "Fair - Needs re-staking", "value": "fair"}, {"label": "Poor - Torn/displaced", "value": "poor"}, {"label": "N/A", "value": "na"}], "required": true}, {"id": "perimeter_stabilization", "type": "select", "label": "Construction Site Perimeter", "options": [{"label": "Good - Stabilized, no erosion", "value": "good"}, {"label": "Fair - Minor erosion", "value": "fair"}, {"label": "Poor - Active erosion observed", "value": "poor"}], "required": true}, {"id": "stockpile_covers", "type": "select", "label": "Stockpile Covers/Stabilization", "options": [{"label": "Good - Covered/stabilized", "value": "good"}, {"label": "Fair - Partially covered", "value": "fair"}, {"label": "Poor - Uncovered, eroding", "value": "poor"}, {"label": "N/A", "value": "na"}], "required": true}]}, {"id": "site_conditions", "order": 5, "title": "Site Conditions", "fields": [{"id": "discharge_points", "type": "select", "label": "Active Discharge Points", "options": [{"label": "Clear - No visible discharge", "value": "clear"}, {"label": "Turbid discharge observed", "value": "turbid"}, {"label": "Sediment-laden discharge", "value": "sediment_laden"}, {"label": "N/A", "value": "na"}], "required": true}, {"id": "soil_disturbance", "type": "number", "label": "Actively Disturbed Areas (acres)", "required": false, "validation": {"max": 1000, "min": 0, "precision": 0.1}}, {"id": "stabilized_areas", "type": "number", "label": "Stabilized Areas (acres)", "required": false, "validation": {"max": 1000, "min": 0, "precision": 0.1}}, {"id": "accumulated_sediment", "type": "select", "label": "Accumulated Sediment Off-Site", "options": [{"label": "None observed", "value": "none"}, {"label": "Minor - Clean up scheduled", "value": "minor"}, {"label": "Major - Immediate action required", "value": "major"}], "required": true}, {"id": "site_notes", "type": "textarea", "label": "Site Condition Notes", "required": false, "validation": {"maxLength": 1500}, "placeholder": "Describe overall site conditions, erosion, tracking, etc."}]}, {"id": "deficiencies", "order": 6, "title": "Deficiencies & Corrective Actions", "fields": [{"id": "deficiencies_found", "type": "radio", "label": "Were deficiencies found?", "options": [{"label": "Yes", "value": "yes"}, {"label": "No", "value": "no"}], "required": true, "defaultValue": "no"}, {"id": "deficiency_list", "type": "repeater", "label": "Deficiencies", "maxItems": 30, "minItems": 1, "required": true, "itemSchema": {"fields": [{"id": "deficiency", "type": "textarea", "label": "Deficiency Description", "required": true, "validation": {"maxLength": 500}}, {"id": "location", "type": "text", "label": "Location", "required": false, "validation": {"maxLength": 150}}, {"id": "severity", "type": "select", "label": "Severity", "options": [{"label": "Immediate - Active discharge/violation", "value": "immediate"}, {"label": "High - Fix today", "value": "high"}, {"label": "Medium - Fix within 7 days", "value": "medium"}, {"label": "Low - Monitor", "value": "low"}], "required": true}, {"id": "corrective_action", "type": "text", "label": "Required Corrective Action", "required": true, "validation": {"maxLength": 300}}, {"id": "responsible_person", "type": "text", "label": "Responsible Person", "required": true, "validation": {"maxLength": 100}}, {"id": "completion_deadline", "type": "date", "label": "Completion Deadline", "required": true}]}, "conditionalDisplay": {"field": "deficiencies_found", "value": "yes", "operator": "equals"}}]}, {"id": "photos", "order": 7, "title": "Photo Documentation", "fields": [{"id": "inspection_photos", "type": "photo", "label": "BMP/Site Condition Photos", "helpText": "Document BMPs, deficiencies, discharge points, and site conditions", "multiple": true, "required": false, "maxPhotos": 40, "captureGPS": true}]}, {"id": "compliance", "order": 8, "title": "Compliance & SWPPP Updates", "fields": [{"id": "swppp_amendment_needed", "type": "radio", "label": "Does SWPPP need to be amended?", "options": [{"label": "Yes", "value": "yes"}, {"label": "No", "value": "no"}], "helpText": "Changes in operations, site conditions, or BMP effectiveness may require SWPPP update", "required": true, "defaultValue": "no"}, {"id": "amendment_reason", "type": "textarea", "label": "Reason for SWPPP Amendment", "required": true, "validation": {"maxLength": 1000}, "conditionalDisplay": {"field": "swppp_amendment_needed", "value": "yes", "operator": "equals"}}, {"id": "followup_required", "type": "radio", "label": "Is follow-up inspection required?", "options": [{"label": "Yes", "value": "yes"}, {"label": "No", "value": "no"}], "required": true, "defaultValue": "no"}, {"id": "followup_date", "type": "date", "label": "Follow-Up Inspection Date", "required": true, "conditionalDisplay": {"field": "followup_required", "value": "yes", "operator": "equals"}}, {"id": "notes", "type": "textarea", "label": "Additional Notes/Observations", "required": false, "validation": {"maxLength": 2000}, "placeholder": "Any additional observations or recommendations..."}]}, {"id": "signature", "order": 9, "title": "Inspector Certification", "fields": [{"id": "inspector_signature", "type": "signature", "label": "Inspector Signature", "helpText": "I certify this inspection was conducted per EPA CGP 2022 Section 4.4", "required": true, "captureTimestamp": true}]}]}', 'Initial system template from 10-swppp-site-inspection.json', '2025-10-24 13:30:31.427', 'system');
INSERT INTO public.form_template_versions VALUES ('6ae4073f-ea85-4270-8849-9248578f693d', '41190886-307e-45f1-b183-585ef58a8473', 1, '{"sections": [{"id": "log_info", "order": 1, "title": "Daily Log Information", "fields": [{"id": "date", "type": "date", "label": "Date", "required": true, "defaultValue": "{{currentDate}}"}, {"id": "project_name", "type": "text", "label": "Project Name", "readonly": true, "required": true, "defaultValue": "{{projectName}}"}, {"id": "location", "type": "text", "label": "Project Location", "required": true, "defaultValue": "{{projectLocation}}"}, {"id": "inspector_name", "type": "text", "label": "Inspector/Monitor Name", "required": true, "defaultValue": "{{currentUser}}"}, {"id": "jurisdiction", "type": "select", "label": "Jurisdiction", "options": [{"label": "Clark County (Las Vegas area)", "value": "clark_county"}, {"label": "Washoe County (Reno area)", "value": "washoe_county"}, {"label": "Nevada DEP (Outside Clark/Washoe)", "value": "nevada_dep"}, {"label": "Other", "value": "other"}], "helpText": "Select the air quality jurisdiction", "required": true}, {"id": "dust_control_permit", "type": "text", "label": "Dust Control Permit Number", "required": false, "validation": {"maxLength": 100}}]}, {"id": "weather", "order": 2, "title": "Weather Conditions", "fields": [{"id": "temperature", "type": "number", "label": "Temperature (°F)", "required": true, "validation": {"max": 150, "min": -20}}, {"id": "wind_speed", "type": "number", "label": "Wind Speed (mph)", "helpText": "CRITICAL: >15 mph requires increased watering frequency", "required": true, "validation": {"max": 100, "min": 0}}, {"id": "wind_speed_warning", "type": "checkbox", "label": "Wind Speed >15 mph - Increased watering required", "readonly": true, "required": false, "defaultValue": false, "computedValue": "wind_speed > 15"}, {"id": "wind_direction", "type": "select", "label": "Wind Direction", "options": [{"label": "North", "value": "N"}, {"label": "Northeast", "value": "NE"}, {"label": "East", "value": "E"}, {"label": "Southeast", "value": "SE"}, {"label": "South", "value": "S"}, {"label": "Southwest", "value": "SW"}, {"label": "West", "value": "W"}, {"label": "Northwest", "value": "NW"}, {"label": "Calm", "value": "calm"}], "required": true}, {"id": "precipitation", "type": "number", "label": "Precipitation (inches)", "required": false, "validation": {"max": 10, "min": 0, "precision": 0.01}}, {"id": "humidity", "type": "number", "label": "Humidity (%)", "required": false, "validation": {"max": 100, "min": 0}}, {"id": "visibility", "type": "select", "label": "Visibility Conditions", "options": [{"label": "Excellent - >10 miles", "value": "excellent"}, {"label": "Good - 5-10 miles", "value": "good"}, {"label": "Fair - 2-5 miles", "value": "fair"}, {"label": "Poor - <2 miles (dust impact)", "value": "poor"}], "required": true}]}, {"id": "soil_conditions", "order": 3, "title": "Soil Conditions", "fields": [{"id": "soil_moisture", "type": "select", "label": "Soil Moisture Level", "options": [{"label": "Wet", "value": "wet"}, {"label": "Moist", "value": "moist"}, {"label": "Dry", "value": "dry"}, {"label": "Very Dry - High dust potential", "value": "very_dry"}], "required": true}, {"id": "actively_disturbed", "type": "number", "label": "Actively Disturbed Areas (acres)", "helpText": "Projects ≥50 acres require Dust Control Monitor", "required": true, "validation": {"max": 1000, "min": 0, "precision": 0.1}}, {"id": "stabilized_areas", "type": "number", "label": "Stabilized Areas (acres)", "required": false, "validation": {"max": 1000, "min": 0, "precision": 0.1}}]}, {"id": "water_application", "order": 4, "title": "Water Application", "fields": [{"id": "water_trucks", "type": "repeater", "label": "Water Truck Applications", "maxItems": 20, "minItems": 0, "required": false, "itemSchema": {"fields": [{"id": "truck_id", "type": "text", "label": "Truck ID/Operator", "required": true, "validation": {"maxLength": 100}}, {"id": "start_time", "type": "time", "label": "Start Time", "required": true}, {"id": "end_time", "type": "time", "label": "End Time", "required": true}, {"id": "areas_watered", "type": "text", "label": "Areas Watered", "required": true, "validation": {"maxLength": 300}, "placeholder": "Describe locations watered"}, {"id": "gallons_applied", "type": "number", "label": "Gallons Applied (estimate)", "required": false, "validation": {"max": 50000, "min": 0}}, {"id": "application_frequency", "type": "number", "label": "Times Applied Today", "helpText": "Increased frequency if wind >15 mph", "required": false, "validation": {"max": 20, "min": 1}}, {"id": "weather_adjustment", "type": "text", "label": "Weather Adjustment Notes", "required": false, "validation": {"maxLength": 200}, "placeholder": "e.g., Increased frequency due to wind"}]}}, {"id": "total_water_applications", "type": "number", "label": "Total Water Applications Today", "computed": {"formula": "SUM(water_trucks.*.application_frequency)"}, "readonly": true, "required": false}]}, {"id": "dust_palliatives", "order": 5, "title": "Dust Palliatives (Chemical Stabilization)", "fields": [{"id": "palliatives_used", "type": "radio", "label": "Were dust palliatives used today?", "options": [{"label": "Yes", "value": "yes"}, {"label": "No", "value": "no"}], "required": true, "defaultValue": "no"}, {"id": "palliative_applications", "type": "repeater", "label": "Palliative Applications", "maxItems": 15, "minItems": 1, "required": true, "itemSchema": {"fields": [{"id": "product_name", "type": "text", "label": "Palliative Type/Product Name", "required": true, "validation": {"maxLength": 150}}, {"id": "application_areas", "type": "text", "label": "Application Areas", "required": true, "validation": {"maxLength": 300}}, {"id": "application_rate", "type": "text", "label": "Application Rate", "required": true, "validation": {"maxLength": 100}, "placeholder": "e.g., 0.5 gal/sq yd"}, {"id": "application_method", "type": "select", "label": "Application Method", "options": [{"label": "Spray", "value": "spray"}, {"label": "Disk-In", "value": "disk_in"}, {"label": "Other", "value": "other"}], "required": true}, {"id": "contractor", "type": "text", "label": "Contractor/Applicator", "required": false, "validation": {"maxLength": 150}}, {"id": "batch_lot_number", "type": "text", "label": "Batch/Lot Number", "required": false, "validation": {"maxLength": 100}}]}, "conditionalDisplay": {"field": "palliatives_used", "value": "yes", "operator": "equals"}}]}, {"id": "control_measures", "order": 6, "title": "Control Measures Active", "fields": [{"id": "speed_limits", "type": "select", "label": "Speed Limits Enforced", "options": [{"label": "Yes - Posted and enforced", "value": "yes"}, {"label": "No", "value": "no"}, {"label": "N/A", "value": "na"}], "required": true}, {"id": "gravel_roads", "type": "select", "label": "Gravel/Rock Cover on Roads", "options": [{"label": "Adequate coverage", "value": "adequate"}, {"label": "Needs replenishment", "value": "needs_replenish"}, {"label": "None", "value": "none"}, {"label": "N/A", "value": "na"}], "required": true}, {"id": "perimeter_fencing", "type": "select", "label": "Perimeter Fencing/Barriers", "options": [{"label": "Installed", "value": "installed"}, {"label": "Partially installed", "value": "partial"}, {"label": "None", "value": "none"}, {"label": "N/A", "value": "na"}], "required": true}, {"id": "stockpile_tarps", "type": "select", "label": "Tarps on Stockpiles", "options": [{"label": "All covered", "value": "all_covered"}, {"label": "Partially covered", "value": "partial"}, {"label": "None covered", "value": "none"}, {"label": "N/A", "value": "na"}], "required": true}, {"id": "tire_washing", "type": "select", "label": "Vehicle Tire Washing Station", "options": [{"label": "Operational", "value": "operational"}, {"label": "Not operational", "value": "not_operational"}, {"label": "None installed", "value": "none"}, {"label": "N/A", "value": "na"}], "required": true}, {"id": "street_sweeping", "type": "radio", "label": "Street Sweeping Performed Today?", "options": [{"label": "Yes", "value": "yes"}, {"label": "No", "value": "no"}, {"label": "N/A", "value": "na"}], "required": true, "defaultValue": "no"}, {"id": "haul_truck_covers", "type": "select", "label": "Haul Truck Covers/Tarps", "options": [{"label": "All covered", "value": "all_covered"}, {"label": "Some covered", "value": "some_covered"}, {"label": "None covered", "value": "none_covered"}, {"label": "N/A - No haul trucks", "value": "na"}], "required": true}]}, {"id": "inspection_results", "order": 7, "title": "Inspection Results", "fields": [{"id": "visible_dust", "type": "select", "label": "Visible Dust Emissions Observed", "options": [{"label": "None", "value": "none"}, {"label": "Minimal - Acceptable", "value": "minimal"}, {"label": "Moderate - Increase controls", "value": "moderate"}, {"label": "Excessive - Immediate action required", "value": "excessive"}], "required": true}, {"id": "offsite_migration", "type": "select", "label": "Off-Site Dust Migration", "options": [{"label": "None observed", "value": "none"}, {"label": "Minor - Contained quickly", "value": "minor"}, {"label": "Major - Public complaint risk", "value": "major"}], "required": true}, {"id": "control_effectiveness", "type": "select", "label": "Control Measures Effective", "options": [{"label": "Yes - Controls working well", "value": "yes"}, {"label": "Marginal - Need enhancement", "value": "marginal"}, {"label": "No - Controls inadequate", "value": "no"}], "required": true}, {"id": "deficiencies", "type": "textarea", "label": "Deficiencies Identified", "required": false, "validation": {"maxLength": 1500}, "placeholder": "Describe any deficiencies or issues..."}, {"id": "corrective_actions", "type": "textarea", "label": "Corrective Actions Taken", "required": false, "validation": {"maxLength": 1500}, "placeholder": "What actions were taken to address issues?"}, {"id": "action_time", "type": "time", "label": "Time Corrective Actions Completed", "helpText": "When were issues resolved?", "required": false}]}, {"id": "photos", "order": 8, "title": "Photo Documentation", "fields": [{"id": "dust_photos", "type": "photo", "label": "Dust Conditions & Control Measures", "helpText": "Document dust conditions, control measures, and any violations", "multiple": true, "required": false, "maxPhotos": 30, "captureGPS": true}]}, {"id": "compliance", "order": 9, "title": "Compliance Certification", "fields": [{"id": "overall_compliance", "type": "select", "label": "Overall Compliance Status", "options": [{"label": "Compliant - No violations", "value": "compliant"}, {"label": "Minor Issues - Corrected same day", "value": "minor_issues"}, {"label": "Violation - Air quality impacted", "value": "violation"}], "required": true}, {"id": "notes", "type": "textarea", "label": "Additional Notes/Observations", "required": false, "validation": {"maxLength": 2000}, "placeholder": "Any additional information for the daily log..."}, {"id": "inspector_signature", "type": "signature", "label": "Inspector/Monitor Signature", "helpText": "I certify this log accurately reflects dust control activities", "required": true, "captureTimestamp": true}, {"id": "dust_monitor_signature", "type": "signature", "label": "Dust Control Monitor Signature (if ≥50 acres)", "helpText": "Required for projects ≥50 acres actively disturbed", "required": false, "captureTimestamp": true, "conditionalDisplay": {"field": "actively_disturbed", "value": 50, "operator": ">="}}]}]}', 'Initial system template from 11-dust-control-daily-log.json', '2025-10-24 13:30:31.438', 'system');


